local function GetBlocksInPoints(From: Vector3, To: Vector3): {Vector3}
    local Blocks, List = Bedwars.BlockController:getStore(), {}
    for X: number = From.X, To.X do
        for Y: number = From.Y, To.Y do
            for Z: number = From.Z, To.Z do
                local Vector: Vector3 = Vector3.new(X, Y, Z)
                if Blocks:getBlockAt(Vector) then
                    table.insert(List, Vector * 3)
                end
            end
        end
    end
    return List
end
getgenv().getBlocksInPoints = GetBlocksInPoints

local function GetNearGround(Range)
    Range = Vector3.new(3, 3, 3) * (Range or 10)
    local LocalPosition, Distance, Closest = Entity.character.RootPart.Position, 60
    local Blocks = GetBlocksInPoints(Bedwars.BlockController:getBlockPosition(LocalPosition - Range), Bedwars.BlockController:getBlockPosition(LocalPosition + Range))
    for _, v: Vector3 in Blocks do
        if not GetPlacedBlock(v + Vector3.new(0, 3, 0)) then
            local NewDistance: number = (LocalPosition - v).Magnitude
            if NewDistance < Distance then
                Distance, Closest = NewDistance, v + Vector3.new(0, 3, 0)
            end
        end
    end

    table.clear(Blocks)
    return Closest
end
getgenv().getNearGround = GetNearGround

local function GetShieldAttribute(Character: Model): number
    return math.max(Character:GetAttribute("TotalShield") or 0, 0)
end
getgenv().getShieldAttribute = GetShieldAttribute

local function MarkKnockback(DamageTable)
    local Character = DamageTable.entityInstance
    local Multiplier = DamageTable.knockbackMultiplier
    if typeof(Character) ~= "Instance" or (Multiplier and Multiplier.disabled) then
        return
    end

    local Root = Character:IsA("Model") and Character.PrimaryPart or Character:IsA("BasePart") and Character or nil
    local From = DamageTable.fromPosition
    local Impulse
    if Root and From then
        local Direction = Bedwars.KnockbackUtil.getDirection(Root.Position, From)
        if Direction.Magnitude > 0 then
            Impulse = Bedwars.KnockbackUtil.calculateKnockbackVelocity(Direction, 1, Multiplier)
        end
    end

    PredictionLib.markKnockback(Character, Multiplier, Impulse)
end

local function ExpectKnockback(Root, Flight: number?, From: Vector3?, Multiplier)
    if typeof(Root) ~= "Instance" or not Flight or not From then
        return
    end
    if Multiplier and Multiplier.disabled then
        return
    end

    local Direction = Bedwars.KnockbackUtil.getDirection(Root.Position, From)
    if Direction.Magnitude <= 0 then
        return
    end

    PredictionLib.expectKnockback(Root, workspace:GetServerTimeNow() + Flight, Bedwars.KnockbackUtil.calculateKnockbackVelocity(Direction, 1, Multiplier), Multiplier)
end
getgenv().expectKnockback = ExpectKnockback

local function ScanProjectile(Origin: Vector3, Velocity: Vector3, ProjectileType: string, Shooter)
    if not Entity.isAlive then
        return
    end

    local Meta = Bedwars.ProjectileMeta[ProjectileType]
    local Drop: Vector3 = Vector3.new(0, -(Meta and Meta.gravitationalAcceleration or 196.2), 0)

    for _, v: any in Entity.List do
        if v.Character == Shooter then
            continue
        end

        local Root, Hit = v.RootPart
        local RootVelocity: Vector3 = Root.AssemblyLinearVelocity
        for Step: number = 1, 40 do
            local Flight: number = Step * 0.05
            local Point: Vector3 = Origin + Velocity * Flight + Drop * (0.5 * Flight * Flight)
            if (Point - (Root.Position + RootVelocity * Flight)).Magnitude <= v.HipHeight then
                Hit = Flight
                break
            end
        end

        if Hit then
            ExpectKnockback(Root, Hit, Origin, Meta and Meta.knockback)
        end
    end
end
getgenv().scanProjectile = ScanProjectile

local function ReportProjectileHit(DamageTable)
    local Character = DamageTable.entityInstance
    local From = DamageTable.fromEntity
    if (From ~= LocalPlayer.Character and From ~= LocalPlayer) or typeof(Character) ~= "Instance" then
        return
    end

    local Root = Character:IsA("Model") and Character.PrimaryPart or Character:IsA("BasePart") and Character or nil
    if Root then
        PredictionLib.reportHit(Root)
    end
end

local KnockbackSpeed, KnockbackBoost = 0, tick()
local function GetSpeed(): number
    local Multiplier, Increase, Modifiers = 0, true, Bedwars.SprintController:getMovementStatusModifier():getModifiers()
    for Modifier: any in Modifiers do
        local Value = Modifier.constantSpeedMultiplier and Modifier.constantSpeedMultiplier or 0
        if Value and Value > math.max(Multiplier, 1) then
            Increase = false
            Multiplier = Value - (0.06 * math.round(Value))
        end
    end

    for Modifier: any in Modifiers do
        Multiplier += math.max((Modifier.moveSpeedMultiplier or 0) - 1, 0)
    end

    if Multiplier > 0 and Increase then
        Multiplier += 0.16 + (0.02 * math.round(Multiplier))
    end

    return (20 + (KnockbackBoost > tick() and KnockbackSpeed or 0)) * (Multiplier + 1)
end
getgenv().getSpeed = GetSpeed

