    OldWallcheck = Entity.Wallcheck
    local WallcheckParams: RaycastParams = RaycastParams.new()
    WallcheckParams.FilterType = Enum.RaycastFilterType.Exclude

    Entity.Wallcheck = function(Origin: Vector3, Position: Vector3, IgnoreObject, Ent)
        local Character = Ent and Ent.Character
        local SelfCharacter = LocalPlayer.Character
        local SelfRoot = SelfCharacter and SelfCharacter.PrimaryPart
        local TargetRoot = Character and Character.PrimaryPart
        if not SelfRoot or not TargetRoot then
            return OldWallcheck(Origin, Position, IgnoreObject)
        end

        local Humanoid: Humanoid? = SelfCharacter:FindFirstChildWhichIsA("Humanoid")
        local TargetHumanoid: Humanoid? = Character:FindFirstChildWhichIsA("Humanoid")
        local Scale = Humanoid and Humanoid:FindFirstChild("BodyHeightScale")
        local Height: Vector3 = Vector3.new(0, 5 * (Scale and Scale.Value or 1), 0)
        local SelfFeet: Vector3 = SelfRoot.Position - Vector3.new(0, (Humanoid and Humanoid.HipHeight or 0) + (SelfRoot.Size.Y / 2), 0)
        local TargetFeet: Vector3 = TargetRoot.Position - Vector3.new(0, (TargetHumanoid and TargetHumanoid.HipHeight or 0) + (TargetRoot.Size.Y / 2), 0)
        local SelfHead, TargetHead = SelfFeet + Height, TargetFeet + Height
        local SelfMiddle, TargetMiddle = (SelfFeet + SelfHead) / 2, (TargetFeet + TargetHead) / 2

        local Filter = {SelfCharacter, Character}
        for _, v: Instance in CollectionService:GetTagged("DontBlockSwordRaycast") do
            table.insert(Filter, v)
        end
        if typeof(IgnoreObject) == "table" then
            for _, v: Instance in IgnoreObject do
                table.insert(Filter, v)
            end
        end
        WallcheckParams.FilterDescendantsInstances = Filter

        return (Entity.Raycast(SelfFeet, TargetFeet - SelfFeet, WallcheckParams) or Entity.Raycast(TargetFeet, SelfFeet - TargetFeet, WallcheckParams)) and (Entity.Raycast(SelfHead, TargetHead - SelfHead, WallcheckParams) or Entity.Raycast(TargetHead, SelfHead - TargetHead, WallcheckParams)) and (Entity.Raycast(SelfMiddle, TargetMiddle - SelfMiddle, WallcheckParams) or Entity.Raycast(TargetMiddle, SelfMiddle - TargetMiddle, WallcheckParams)) or nil
    end

    local function ClearStaleHooks()
        if not isexecutorclosure then
            return
        end
        local Seen = {}
        local function Clear(Object)
            if type(Object) ~= "table" or Seen[Object] then
                return
            end
            Seen[Object] = true
            local Meta = getmetatable(Object)
            local Class = type(Meta) == "table" and rawget(Meta, "__index")
            if type(Class) ~= "table" then
                return
            end
            for Key: string, Value: any in Object do
                if type(Value) == "function" and isexecutorclosure(Value) and type(Class[Key]) == "function" then
                    rawset(Object, Key, nil)
                end
            end
        end
        pcall(function()
            for _, v: any in Knit.Controllers do
                Clear(v)
            end
            for _, v: any in Bedwars do
                Clear(v)
            end
        end)
    end
    ClearStaleHooks()

    OldBreak = Bedwars.BlockController.isBlockBreakable
    OldHit = Bedwars.BlockBreaker.hitBlock

    Client.Get = function(self, RemoteName: string)
        local Remote = OldGet(self, RemoteName)

        if RemoteName == "SwordHit" then
            return {
                instance = Remote.instance,
                SendToServer = function(_, AttackTable, ...)
                    local SelfPosition: Vector3 = AttackTable.validate.selfPosition.value
                    local TargetPosition: Vector3 = AttackTable.validate.targetPosition.value
                    Store.attackReach = ((SelfPosition - TargetPosition).Magnitude * 100) // 1 / 100
                    Store.attackReachUpdate = tick() + 1

                    if Reach.Enabled or HitBoxes.Enabled then
                        local Delta: Vector3 = TargetPosition - SelfPosition
                        AttackTable.validate.raycast = AttackTable.validate.raycast or {}
                        AttackTable.validate.selfPosition.value += Delta.Magnitude > 0.001 and Delta.Unit * math.max(Delta.Magnitude - (GetReach(AttackTable.weapon) - 0.001), 0) or Vector3.zero
                    end

                    if ChargeSpoof.Enabled and AttackTable.chargedAttack then
                        AttackTable.chargedAttack.chargeRatio = math.max(AttackTable.chargedAttack.chargeRatio or 0, ChargeRatio.Value / 100)
                    end

                    return Remote:SendToServer(AttackTable, ...)
                end
            }
        elseif TrapDisabler.Enabled and (RemoteName == "StepOnSnapTrap" and TrapSnap.Enabled or RemoteName == "TriggerInvisibleLandmine" and TrapMine.Enabled or RemoteName == "StepOnTeleportBlock" and TrapTeleport.Enabled or RemoteName == "StepOnVoidPortal" and TrapPortal.Enabled) then
            return {SendToServer = function() end}
        elseif KnockbackSpoof.Enabled and RemoteName == "AckKnockback" then
            return {
                instance = Remote.instance,
                SendToServer = function(_, AckTable)
                    if KnockbackMode.Value == "Drop" then
                        Store.knockbackAcks = (Store.knockbackAcks or 0) + 1
                        return
                    end

                    if KnockbackMode.Value == "Rewind" and typeof(AckTable.playerPosition) == "Vector3" and Entity.isAlive then
                        AckTable.playerPosition -= Entity.character.RootPart.AssemblyLinearVelocity * (KnockbackRewind.Value / 1000)
                    end

                    Store.knockbackAcks = (Store.knockbackAcks or 0) + 1
                    if KnockbackDelay.Value > 0 then
                        task.delay(KnockbackDelay.Value / 1000, function()
                            Remote:SendToServer(AckTable)
                        end)
                        return
                    end

                    return Remote:SendToServer(AckTable)
                end
            }
        end

        return Remote
    end

