Run(function()
	local HitAccuracy
	local ShowColor
	local HideUnused
	local Sources: {string} = {"ProjectileAura", "ProjectileAimbot", "SilentAim", "TerraAimbot"}
	local Rows = {}
	local Holder: Frame?
	
	local function AddRow(Name: string)
	    local Row: Frame = Instance.new("Frame")
	    Row.BackgroundTransparency = 1
	    Row.Name = Name
	    Row.Size = UDim2.new(1, 0, 0, 20)
	    Row.Parent = Holder
	    local Title: TextLabel = Instance.new("TextLabel")
	    Title.BackgroundTransparency = 1
	    Title.FontFace = UIPallet.Font
	    Title.Position = UDim2.fromOffset(10, 0)
	    Title.Size = UDim2.new(1, -20, 1, 0)
	    Title.Text = Name
	    Title.TextColor3 = Color3.new(1, 1, 1)
	    Title.TextSize = 14
	    Title.TextStrokeColor3 = Color3.new()
	    Title.TextStrokeTransparency = 0.8
	    Title.TextXAlignment = Enum.TextXAlignment.Left
	    Title.Parent = Row
	    local Value: TextLabel = Title:Clone()
	    Value.Name = "Value"
	    Value.Text = "--"
	    Value.TextXAlignment = Enum.TextXAlignment.Right
	    Value.Parent = Row
	
	    Rows[Name] = {Object = Row, Title = Title, Value = Value}
	end
	
	local function Refresh()
	    if vape.ThreadFix then
	        setthreadidentity(8)
	    end
	
	    local Shown: number = 0
	    for _, v: string in Sources do
	        local Chance = Store.hitchance[v]
	        local Live = Chance and (tick() - Chance.Clock) < 2
	        local Row = Rows[v]
	        Row.Object.Visible = Live or not HideUnused.Enabled
	
	        if Row.Object.Visible then
	            Row.Object.Position = UDim2.fromOffset(0, 6 + (Shown * 20))
	            Row.Value.Text = Live and `{math.round(Chance.Value * 100)}%` or "--"
	            Row.Value.TextColor3 = (Live and ShowColor.Enabled) and Color3.fromHSV(Chance.Value * 0.33, 0.75, 1) or Color3.new(1, 1, 1)
	            Shown += 1
	        end
	    end
	
	    Rows.Waiting.Object.Visible = Shown == 0
	    Holder.Size = UDim2.fromOffset(190, 12 + (math.max(Shown, 1) * 20))
	end
	
	HitAccuracy = vape:CreateOverlay({
	    Name = "Hit Accuracy",
	    Icon = GetVapeAsset("kingvape/assets/new/aim.png"),
	    Size = UDim2.fromOffset(18, 12),
	    Position = UDim2.fromOffset(11, 14),
	    Function = function(Callback: boolean)
	        if Callback then
	            repeat
	                Refresh()
	                task.wait(0.05)
	            until not HitAccuracy.Button or not HitAccuracy.Button.Enabled
	        end
	    end
	})
	
	HitAccuracy:CreateFont({
	    Name = "Font",
	    Blacklist = "Gotham",
	    Function = function(Val: Font)
	        for _, v: {Object: Frame, Title: TextLabel, Value: TextLabel} in Rows do
	            v.Title.FontFace = Val
	            v.Value.FontFace = Val
	        end
	    end
	})
	HideUnused = HitAccuracy:CreateToggle({
	    Name = "Hide unused",
	    Function = function()
	        if Holder then
	            Refresh()
	        end
	    end,
	    Default = true,
	    Tooltip = "Leaves out a module until it is actually aiming at someone"
	})
	ShowColor = HitAccuracy:CreateToggle({
	    Name = "Color the number",
	    Default = true,
	    Tooltip = "Red through green as the chance climbs"
	})
	HitAccuracy:CreateColorSlider({
	    Name = "Background Color",
	    DefaultValue = 0,
	    DefaultOpacity = 0.5,
	    Function = function(Hue: number, Sat: number, Val: number, Opacity: number)
	        if Holder then
	            Holder.BackgroundColor3 = Color3.fromHSV(Hue, Sat, Val)
	            Holder.BackgroundTransparency = 1 - Opacity
	        end
	    end
	})
	
	Holder = Instance.new("Frame")
	Holder.BackgroundColor3 = Color3.new()
	Holder.BackgroundTransparency = 0.5
	Holder.Size = UDim2.fromOffset(190, 32)
	Holder.Parent = HitAccuracy.Children
	local Corner: UICorner = Instance.new("UICorner")
	Corner.CornerRadius = UDim.new(0, 5)
	Corner.Parent = Holder
	AddBlur(Holder)
	for _, v: string in Sources do
	    AddRow(v)
	end
	AddRow("Waiting")
	Rows.Waiting.Object.Position = UDim2.fromOffset(0, 6)
	Rows.Waiting.Title.Text = "Hit chance"
	Refresh()
	vape:Clean(HitAccuracy.Children:GetPropertyChangedSignal("AbsolutePosition"):Connect(function()
	    if vape.ThreadFix then
	        setthreadidentity(8)
	    end
	
	    local NewSide: boolean = HitAccuracy.Children.AbsolutePosition.X > (vape.gui.AbsoluteSize.X / 2)
	    Holder.AnchorPoint = Vector2.new(NewSide and 1 or 0, 0)
	    Holder.Position = UDim2.fromScale(NewSide and 1 or 0, 0)
	end))
end)

Run(function()
	local InventoryESP
	local Armor
	local Empty
	local BackgroundColor = {}
	local Window, Headshot, NameTag, Grid, ArmorHolder, ArmorDivider
	local Slots, ArmorSlots = {}, {}
	local SlotCount: number = 24
	local SlotSize: number = 32
	local SlotPadding: number = 4
	local Columns: number = 6
	local HeaderHeight: number = 46
	
	local function CreateSlot(Parent: Instance)
	    local Slot: Frame = Instance.new("Frame")
	    Slot.Size = UDim2.fromOffset(SlotSize, SlotSize)
	    Slot.BackgroundColor3 = Color.Dark(UIPallet.Main, 0.02)
	    Slot.BorderSizePixel = 0
	    Slot.Visible = false
	    Slot.Parent = Parent
	    local Corner: UICorner = Instance.new("UICorner")
	    Corner.CornerRadius = UDim.new(0, 4)
	    Corner.Parent = Slot
	    local Stroke: UIStroke = Instance.new("UIStroke")
	    Stroke.Color = Color.Light(UIPallet.Main, 0.034)
	    Stroke.Parent = Slot
	    local Icon: ImageLabel = Instance.new("ImageLabel")
	    Icon.Name = "Icon"
	    Icon.Size = UDim2.fromOffset(SlotSize - 8, SlotSize - 8)
	    Icon.Position = UDim2.fromScale(0.5, 0.5)
	    Icon.AnchorPoint = Vector2.new(0.5, 0.5)
	    Icon.BackgroundTransparency = 1
	    Icon.Parent = Slot
	    local Amount: TextLabel = Instance.new("TextLabel")
	    Amount.Name = "Amount"
	    Amount.Size = UDim2.fromOffset(SlotSize - 4, 11)
	    Amount.Position = UDim2.fromOffset(0, SlotSize - 13)
	    Amount.BackgroundTransparency = 1
	    Amount.Text = ""
	    Amount.TextXAlignment = Enum.TextXAlignment.Right
	    Amount.TextSize = 11
	    Amount.TextColor3 = UIPallet.Text
	    Amount.TextStrokeColor3 = Color3.new()
	    Amount.TextStrokeTransparency = 0.4
	    Amount.FontFace = UIPallet.Font
	    Amount.Parent = Slot
	    return Slot
	end
	
	local function SetSlot(Slot: Frame, Item, Highlight: boolean?)
	    if not Item or not Item.itemType then
	        Slot.Visible = false
	        return
	    end
	
	    Slot.Visible = true
	    Slot.Icon.Image = Bedwars.getIcon(Item, true)
	    Slot.Amount.Text = (Item.amount or 1) > 1 and tostring(Item.amount) or ""
	    Slot.UIStroke.Color = Highlight and Color3.fromHSV(BackgroundColor.Hue, BackgroundColor.Sat, BackgroundColor.Value) or Color.Light(UIPallet.Main, 0.034)
	end
	
	local function Refresh()
	    local Ent, Highest = nil, tick()
	    for Target: any, Expiry: number in TargetInfo.Targets do
	        if Expiry < tick() then
	            TargetInfo.Targets[Target] = nil
	            continue
	        end
	        if Expiry > Highest then
	            Ent, Highest = Target, Expiry
	        end
	    end
	
	    local Player: Player? = Ent and Ent.Player or nil
	    local Inventory = Player and Store.inventories[Player] or nil
	    if not Ent or (not Inventory and not Empty.Enabled) then
	        Window.Visible = false
	        return
	    end
	
	    Window.Visible = true
	    NameTag.Text = Player and Player.DisplayName or (Ent.Character and Ent.Character.Name) or ""
	    Headshot.Image = `rbxthumb://type=AvatarHeadShot&id={Player and Player.UserId or 1}&w=420&h=420`
	
	    Inventory = Inventory or {items = {}, armor = {}}
	    local Hand = Inventory.hand
	    local Shown: number = 0
	    for i: number, v: Frame in Slots do
	        local Item = Inventory.items[i]
	        SetSlot(v, Item, Item and Hand and Item.tool == Hand.tool)
	        if v.Visible then
	            Shown = i
	        end
	    end
	
	    local Rows: number = math.max(math.ceil(Shown / Columns), 1)
	    local GridHeight: number = (Rows * SlotSize) + ((Rows - 1) * SlotPadding)
	    Grid.Size = UDim2.new(1, -28, 0, GridHeight)
	
	    local Height: number = HeaderHeight + 10 + GridHeight + 10
	    if Armor.Enabled then
	        ArmorDivider.Visible = true
	        ArmorHolder.Visible = true
	        ArmorDivider.Position = UDim2.fromOffset(0, Height - 1)
	
	        for i: number = 1, 3 do
	            SetSlot(ArmorSlots[i], Inventory.armor[i + 3])
	        end
	        SetSlot(ArmorSlots[4], Hand, true)
	
	        ArmorHolder.Position = UDim2.fromOffset(14, Height + 9)
	        Height += SlotSize + 19
	    else
	        ArmorDivider.Visible = false
	        ArmorHolder.Visible = false
	    end
	
	    Window.Size = UDim2.fromOffset(240, Height)
	end
	
	InventoryESP = vape.Categories.Render:CreateModule({
	    Name = "InventoryESP",
	    Function = function(Callback: boolean)
	        if Callback then
	            if not Window then
	                Window = Instance.new("Frame")
	                Window.Name = "InventoryESP"
	                Window.Size = UDim2.fromOffset(240, HeaderHeight)
	                Window.Position = UDim2.fromOffset(12, 260)
	                Window.BackgroundColor3 = Color3.fromHSV(BackgroundColor.Hue, BackgroundColor.Sat, BackgroundColor.Value)
	                Window.BackgroundTransparency = 1 - BackgroundColor.Opacity
	                Window.Visible = false
	                Window.Parent = vape.gui.ScaledGui
	                AddBlur(Window)
	                local Corner: UICorner = Instance.new("UICorner")
	                Corner.CornerRadius = UDim.new(0, 5)
	                Corner.Parent = Window
	
	                Headshot = Instance.new("ImageLabel")
	                Headshot.Name = "Headshot"
	                Headshot.Size = UDim2.fromOffset(26, 26)
	                Headshot.Position = UDim2.fromOffset(14, 11)
	                Headshot.BackgroundColor3 = Color.Dark(UIPallet.Main, 0.02)
	                Headshot.Image = ""
	                Headshot.Parent = Window
	                local HeadCorner: UICorner = Instance.new("UICorner")
	                HeadCorner.CornerRadius = UDim.new(0, 4)
	                HeadCorner.Parent = Headshot
	
	                NameTag = Instance.new("TextLabel")
	                NameTag.Name = "Name"
	                NameTag.Size = UDim2.new(1, -60, 0, 26)
	                NameTag.Position = UDim2.fromOffset(48, 11)
	                NameTag.BackgroundTransparency = 1
	                NameTag.Text = ""
	                NameTag.TextXAlignment = Enum.TextXAlignment.Left
	                NameTag.TextSize = 13
	                NameTag.TextColor3 = UIPallet.Text
	                NameTag.TextTruncate = Enum.TextTruncate.AtEnd
	                NameTag.FontFace = UIPallet.Font
	                NameTag.Parent = Window
	
	                local Divider: Frame = Instance.new("Frame")
	                Divider.Name = "Divider"
	                Divider.Size = UDim2.new(1, 0, 0, 1)
	                Divider.Position = UDim2.fromOffset(0, HeaderHeight - 1)
	                Divider.BackgroundColor3 = Color.Light(UIPallet.Main, 0.04)
	                Divider.BorderSizePixel = 0
	                Divider.Parent = Window
	
	                Grid = Instance.new("Frame")
	                Grid.Name = "Items"
	                Grid.Size = UDim2.new(1, -28, 0, 0)
	                Grid.Position = UDim2.fromOffset(14, HeaderHeight + 10)
	                Grid.BackgroundTransparency = 1
	                Grid.Parent = Window
	                local Layout: UIGridLayout = Instance.new("UIGridLayout")
	                Layout.CellSize = UDim2.fromOffset(SlotSize, SlotSize)
	                Layout.CellPadding = UDim2.fromOffset(SlotPadding, SlotPadding)
	                Layout.SortOrder = Enum.SortOrder.LayoutOrder
	                Layout.Parent = Grid
	
	                for i: number = 1, SlotCount do
	                    local Slot: Frame = CreateSlot(Grid)
	                    Slot.LayoutOrder = i
	                    Slots[i] = Slot
	                end
	
	                ArmorDivider = Instance.new("Frame")
	                ArmorDivider.Name = "ArmorDivider"
	                ArmorDivider.Size = UDim2.new(1, 0, 0, 1)
	                ArmorDivider.BackgroundColor3 = Color.Light(UIPallet.Main, 0.04)
	                ArmorDivider.BorderSizePixel = 0
	                ArmorDivider.Parent = Window
	
	                ArmorHolder = Instance.new("Frame")
	                ArmorHolder.Name = "Armor"
	                ArmorHolder.Size = UDim2.fromOffset(240, SlotSize)
	                ArmorHolder.BackgroundTransparency = 1
	                ArmorHolder.Parent = Window
	                local ArmorLayout: UIListLayout = Instance.new("UIListLayout")
	                ArmorLayout.FillDirection = Enum.FillDirection.Horizontal
	                ArmorLayout.Padding = UDim.new(0, SlotPadding)
	                ArmorLayout.Parent = ArmorHolder
	
	                for i: number = 1, 4 do
	                    local Slot: Frame = CreateSlot(ArmorHolder)
	                    Slot.LayoutOrder = i
	                    ArmorSlots[i] = Slot
	                end
	            end
	
	            repeat
	                Refresh()
	                task.wait(0.1)
	            until not InventoryESP.Enabled
	
	            Window.Visible = false
	        elseif Window then
	            Window.Visible = false
	        end
	    end,
	    Tooltip = "Shows the inventory of whoever you are currently targeting"
	})
	
	Armor = InventoryESP:CreateToggle({
	    Name = "Show armor",
	    Function = function()
	        if InventoryESP.Enabled then
	            Refresh()
	        end
	    end,
	    Default = true
	})
	Empty = InventoryESP:CreateToggle({
	    Name = "Show without data",
	    Tooltip = "Keeps the panel up when the server has not shared their inventory yet"
	})
	BackgroundColor = InventoryESP:CreateColorSlider({
	    Name = "Background Color",
	    DefaultValue = 0,
	    DefaultOpacity = 0.5,
	    Function = function(Hue: number, Sat: number, Val: number, Opacity: number)
	        if Window then
	            Window.BackgroundColor3 = Color3.fromHSV(Hue, Sat, Val)
	            Window.BackgroundTransparency = 1 - Opacity
	        end
	    end
	})
end)

Run(function()
	local ItemESP
	local Distance
	local Transparency
	local Scale
	local WhitelistOnly
	local Whitelist = {}
	local Reference = {}
	local Labels = setmetatable({}, {__mode = "k"})
	local Folder: Folder = Instance.new("Folder")
	Folder.Parent = vape.gui
	
	local function Added(Ent: Instance)
	    local Name: string = Bedwars.ItemMeta[Ent.Name] and Bedwars.ItemMeta[Ent.Name].displayName or Ent.Name
	    if WhitelistOnly.Enabled and not table.find(Whitelist.ListEnabled, Name:lower()) then return end
	
	    local Amount: number = Ent:GetAttribute("Amount") or 1
	    local NameTag: TextLabel = Instance.new("TextLabel")
	    NameTag.Name = Name
	    NameTag.Text = `{Name}{Amount >= 2 and ` x{Amount}` or ""}`
	    NameTag.TextSize = 14 * Scale.Value
	    NameTag.Font = Enum.Font.Arial
	    local Size: Vector2 = GetFontBounds(RemoveTags(NameTag.Text), NameTag.TextSize, NameTag.FontFace)
	    NameTag.Size = UDim2.fromOffset(Size.X + 8, Size.Y + 7)
	    NameTag.AnchorPoint = Vector2.new(0.5, 1)
	    NameTag.BackgroundColor3 = Color3.new()
	    NameTag.BackgroundTransparency = Transparency.Value
	    NameTag.BorderSizePixel = 0
	    NameTag.Visible = false
	    NameTag.TextColor3 = Color3.new(1, 1, 1)
	    NameTag.RichText = true
	    NameTag.Parent = Folder
	    Labels[Ent] = nil
	    Reference[Ent] = NameTag
	end
	
	ItemESP = vape.Categories.Render:CreateModule({
	    Name = "ItemESP",
	    Function = function(Callback: boolean)
	        if Callback then
	            for _, v: Instance in CollectionService:GetTagged("ItemDrop") do
	                Added(v)
	            end
	            ItemESP:Clean(CollectionService:GetInstanceAddedSignal("ItemDrop"):Connect(Added))
	            ItemESP:Clean(CollectionService:GetInstanceRemovedSignal("ItemDrop"):Connect(function(Ent: Instance)
	                if Reference[Ent] then
	                    Reference[Ent]:Destroy()
	                    Reference[Ent] = nil
	                end
	            end))
	            ItemESP:Clean(RunService.PreRender:Connect(function()
	                local LocalPosition = Entity.isAlive and Entity.character.RootPart.Position
	
	                for Item: BasePart, v: TextLabel in Reference do
	                    if not Item.Parent then
	                        v:Destroy()
	                        Reference[Item] = nil
	                        continue
	                    end
	
	                    local ScreenPos, Visible = Camera:WorldToViewportPoint(Item.Position + Vector3.new(0, 1, 0))
	                    v.Visible = Visible and Item.Position.Y > -200
	                    if not v.Visible then continue end
	
	                    local Amount: number = Item:GetAttribute("Amount") or 1
	                    local ItemDistance: number? = Distance.Enabled and (LocalPosition and math.floor((LocalPosition - Item.Position).Magnitude) or 0) or nil
	                    local Label = Labels[Item]
	
	                    if not Label or Label.Amount ~= Amount or Label.Distance ~= ItemDistance then
	                        local Text: string = `{v.Name}{Amount >= 2 and ` x{Amount}` or ""}`
	                        if ItemDistance then
	                            Text = `<font color="rgb(85, 255, 85)">[</font><font color="rgb(255, 255, 255)">{ItemDistance}</font><font color="rgb(85, 255, 85)">]</font> {Text}`
	                        end
	
	                        Labels[Item] = {Amount = Amount, Distance = ItemDistance}
	                        v.Text = Text
	                        local Size: Vector2 = GetFontBounds(RemoveTags(Text), v.TextSize, v.FontFace)
	                        v.Size = UDim2.fromOffset(Size.X + 8, Size.Y + 7)
	                    end
	                    v.Position = UDim2.fromOffset(ScreenPos.X, ScreenPos.Y)
	                end
	            end))
	        else
	            for Item: Instance, v: TextLabel in Reference do
	                v:Destroy()
	                Reference[Item] = nil
	            end
	        end
	    end,
	    Tooltip = "Renders tags dropped items"
	})
	
	Distance = ItemESP:CreateToggle({
	    Name = "Distance",
	    Tooltip = "Shows the distance of the item"
	})
	Transparency = ItemESP:CreateSlider({
	    Name = "Transparency",
	    Min = 0,
	    Max = 1,
	    Decimal = 100,
	    Function = function(Value: number)
	        if not ItemESP.Enabled then return end
	        for _, v: TextLabel in Reference do
	            v.BackgroundTransparency = Value
	        end
	    end,
	    Default = 0.5
	})
	Scale = ItemESP:CreateSlider({
	    Name = "Scale",
	    Min = 0.1,
	    Max = 1.5,
	    Decimal = 10,
	    Function = function(Value: number)
	        if not ItemESP.Enabled then return end
	        for _, v: TextLabel in Reference do
	            v.TextSize = 14 * Value
	            local Size: Vector2 = GetFontBounds(RemoveTags(v.Text), v.TextSize, v.FontFace)
	            v.Size = UDim2.fromOffset(Size.X + 8, Size.Y + 7)
	        end
	    end,
	    Default = 1
	})
	WhitelistOnly = ItemESP:CreateToggle({
	    Name = "Whitelist Only",
	    Function = function(Callback: boolean)
	        if Whitelist.Object then
	            Whitelist.Object.Visible = Callback
	        end
	        if ItemESP.Enabled then
	            ItemESP:Toggle()
	            ItemESP:Toggle()
	        end
	    end,
	    Tooltip = "Only renders whitelisted items"
	})
	Whitelist = ItemESP:CreateTextList({
	    Name = "Allowed items",
	    Function = function()
	        if ItemESP.Enabled then
	            ItemESP:Toggle()
	            ItemESP:Toggle()
	        end
	    end,
	    Darker = true,
	    Visible = false
	})
end)

Run(function()
	local ItemPlates
	local Whitelist
	local Background
	local Color = {}
	local Reference = {}
	local Folder: Folder = Instance.new("Folder")
	Folder.Parent = vape.gui
	
	local function ScanSide(self, Start: Vector3, Found: {string})
	    for _, v: Vector3 in Sides do
	        for i: number = 1, 15 do
	            local Block: Instance? = GetPlacedBlock(Start + (v * i))
	            if not Block or Block == self then break end
	            if not Block:GetAttribute("NoBreak") and not table.find(Found, Block.Name) then
	                table.insert(Found, Block.Name)
	            end
	        end
	    end
	end
	
	local function RefreshAdornee(Billboard: BillboardGui)
	    local Adornee: Instance? = Billboard.Adornee
	    if not Adornee or not Adornee.Parent then
	        Billboard.Enabled = false
	        return
	    end
	
	    for _, v: Instance in Billboard.Frame:GetChildren() do
	        if v:IsA("ImageLabel") then
	            v:Destroy()
	        end
	    end
	
	    local AlreadyGot: {string} = {}
	    ScanSide(Adornee, Adornee.Position, AlreadyGot)
	    ScanSide(Adornee, Adornee.Position + Vector3.new(0, 0, 3), AlreadyGot)
	    table.sort(AlreadyGot, function(A: string, B: string)
	        local First = Bedwars.ItemMeta[A]
	        local Second = Bedwars.ItemMeta[B]
	        return (First and First.block and First.block.health or 0) > (Second and Second.block and Second.block.health or 0)
	    end)
	    Billboard.Enabled = #AlreadyGot > 0
	
	    for _, v: string in AlreadyGot do
	        local BlockImage: ImageLabel = Instance.new("ImageLabel")
	        BlockImage.Size = UDim2.fromOffset(32, 32)
	        BlockImage.BackgroundTransparency = 1
	        BlockImage.Image = Bedwars.getIcon({itemType = v}, true)
	        BlockImage.Parent = Billboard.Frame
	    end
	end
	
	local function Added(Part: Instance)
	    if not table.find(Whitelist.ListEnabled, Part.Name) or Reference[Part] then return end
	
	    local Billboard: BillboardGui = Instance.new("BillboardGui")
	    Billboard.Parent = Folder
	    Billboard.Name = "bed"
	    Billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
	    Billboard.Size = UDim2.fromOffset(36, 36)
	    Billboard.AlwaysOnTop = true
	    Billboard.ClipsDescendants = false
	    Billboard.Adornee = Part
	    local Blur: ImageLabel = AddBlur(Billboard)
	    Blur.Visible = Background.Enabled
	    local Frame: Frame = Instance.new("Frame")
	    Frame.Size = UDim2.fromScale(1, 1)
	    Frame.BackgroundColor3 = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
	    Frame.BackgroundTransparency = 1 - (Background.Enabled and Color.Opacity or 0)
	    Frame.Parent = Billboard
	    local Layout: UIListLayout = Instance.new("UIListLayout")
	    Layout.FillDirection = Enum.FillDirection.Horizontal
	    Layout.Padding = UDim.new(0, 4)
	    Layout.VerticalAlignment = Enum.VerticalAlignment.Center
	    Layout.HorizontalAlignment = Enum.HorizontalAlignment.Center
	    Layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
	        Billboard.Size = UDim2.fromOffset(math.max(Layout.AbsoluteContentSize.X + 4, 36), 36)
	    end)
	    Layout.Parent = Frame
	    local Corner: UICorner = Instance.new("UICorner")
	    Corner.CornerRadius = UDim.new(0, 4)
	    Corner.Parent = Frame
	    Reference[Part] = Billboard
	    RefreshAdornee(Billboard)
	end
	
	ItemPlates = vape.Categories.Render:CreateModule({
	    Name = "ItemPlates",
	    Function = function(Callback: boolean)
	        if Callback then
	            for _, v: Instance in CollectionService:GetTagged("block") do
	                task.spawn(Added, v)
	            end
	            ItemPlates:Clean(VapeEvents.PlaceBlockEvent.Event:Connect(function(Data)
	                local Position: Vector3 = Data.blockRef.blockPosition * 3
	                for Block: BasePart, v: BillboardGui in Reference do
	                    if (Position - Block.Position).Magnitude <= 30 then
	                        RefreshAdornee(v)
	                    end
	                end
	            end))
	            ItemPlates:Clean(VapeEvents.BreakBlockEvent.Event:Connect(function(Data)
	                local Position: Vector3 = Data.blockRef.blockPosition * 3
	                for Block: BasePart, v: BillboardGui in Reference do
	                    if (Position - Block.Position).Magnitude <= 30 then
	                        RefreshAdornee(v)
	                    end
	                end
	            end))
	            ItemPlates:Clean(CollectionService:GetInstanceAddedSignal("block"):Connect(Added))
	            ItemPlates:Clean(CollectionService:GetInstanceRemovedSignal("block"):Connect(function(Part: Instance)
	                if Reference[Part] then
	                    Reference[Part]:Destroy()
	                    Reference[Part] = nil
	                end
	            end))
	        else
	            table.clear(Reference)
	            Folder:ClearAllChildren()
	        end
	    end,
	    Tooltip = "Displays surrounding blocks around the item."
	})
	
	Whitelist = ItemPlates:CreateTextList({
	    Name = "Whitelist",
	    Function = function()
	        if ItemPlates.Enabled then
	            ItemPlates:Toggle()
	            ItemPlates:Toggle()
	        end
	    end,
	    Default = {"beehive"}
	})
	Background = ItemPlates:CreateToggle({
	    Name = "Background",
	    Function = function(Callback: boolean)
	        if Color.Object then
	            Color.Object.Visible = Callback
	        end
	        for _, v: BillboardGui in Reference do
	            v.Frame.BackgroundTransparency = 1 - (Callback and Color.Opacity or 0)
	            v.Blur.Visible = Callback
	        end
	    end,
	    Default = true
	})
	Color = ItemPlates:CreateColorSlider({
	    Name = "Background Color",
	    DefaultValue = 0,
	    DefaultOpacity = 0.5,
	    Function = function(Hue: number, Sat: number, Val: number, Opacity: number)
	        for _, v: BillboardGui in Reference do
	            v.Frame.BackgroundColor3 = Color3.fromHSV(Hue, Sat, Val)
	            v.Frame.BackgroundTransparency = 1 - (Background.Enabled and Opacity or 0)
	        end
	    end,
	    Darker = true
	})
end)

Run(function()
	local KitESP
	local Background
	local Color = {}
	local Scale
	local Reference = {}
	local Connections: {RBXScriptConnection} = {}
	local Folder: Folder = Instance.new("Folder")
	Folder.Parent = vape.gui
	
	local ESPKits: {[string]: {string}} = {
	    alchemist = {"alchemist_ingedients", "wild_flower"},
	    beekeeper = {"bee", "bee"},
	    bigman = {"treeOrb", "natures_essence_1"},
	    ghost_catcher = {"ghost", "ghost_orb"},
	    metal_detector = {"hidden-metal", "iron"},
	    sheep_herder = {"SheepModel", "purple_hay_bale"},
	    sorcerer = {"alchemy_crystal", "wild_flower"},
	    star_collector = {"stars", "crit_star"}
	}
	
	local function Added(Ent: Instance, Icon: string)
	    local Part = Ent:IsA("BasePart") and Ent or Ent:IsA("Model") and (Ent.PrimaryPart or Ent:FindFirstChild("Root") or Ent:FindFirstChildWhichIsA("BasePart"))
	    if not Part or Reference[Ent] then return end
	
	    local Billboard: BillboardGui = Instance.new("BillboardGui")
	    Billboard.Name = Icon
	    Billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0)
	    Billboard.Size = UDim2.fromOffset(36 * Scale.Value, 36 * Scale.Value)
	    Billboard.AlwaysOnTop = true
	    Billboard.ClipsDescendants = false
	    Billboard.Adornee = Part
	    Billboard.Parent = Folder
	    local Blur: ImageLabel = AddBlur(Billboard)
	    Blur.Size = UDim2.new(1, 89 * Scale.Value, 1, 52 * Scale.Value)
	    Blur.Position = UDim2.fromOffset(-48 * Scale.Value, -31 * Scale.Value)
	    Blur.Visible = Background.Enabled
	    local Image: ImageLabel = Instance.new("ImageLabel")
	    Image.Size = UDim2.fromOffset(36 * Scale.Value, 36 * Scale.Value)
	    Image.Position = UDim2.fromScale(0.5, 0.5)
	    Image.AnchorPoint = Vector2.new(0.5, 0.5)
	    Image.BackgroundColor3 = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
	    Image.BackgroundTransparency = 1 - (Background.Enabled and Color.Opacity or 0)
	    Image.BorderSizePixel = 0
	    Image.Image = Bedwars.getIcon({itemType = Icon}, true)
	    Image.Parent = Billboard
	    local Corner: UICorner = Instance.new("UICorner")
	    Corner.CornerRadius = UDim.new(0, 4)
	    Corner.Parent = Image
	    Reference[Ent] = Billboard
	end
	
	KitESP = vape.Categories.Render:CreateModule({
	    Name = "KitESP",
	    Function = function(Callback: boolean)
	        if Callback then
	            local Current: string?
	            repeat
	                if Store.equippedKit ~= Current then
	                    Current = Store.equippedKit
	                    for _, v: RBXScriptConnection in Connections do
	                        v:Disconnect()
	                    end
	                    table.clear(Connections)
	                    table.clear(Reference)
	                    Folder:ClearAllChildren()
	
	                    local Kit: {string}? = ESPKits[Current]
	                    if Kit then
	                        table.insert(Connections, CollectionService:GetInstanceAddedSignal(Kit[1]):Connect(function(Ent: Instance)
	                            Added(Ent, Kit[2])
	                        end))
	                        table.insert(Connections, CollectionService:GetInstanceRemovedSignal(Kit[1]):Connect(function(Ent: Instance)
	                            if Reference[Ent] then
	                                Reference[Ent]:Destroy()
	                                Reference[Ent] = nil
	                            end
	                        end))
	                        for _, v: Instance in CollectionService:GetTagged(Kit[1]) do
	                            Added(v, Kit[2])
	                        end
	                    end
	                end
	                task.wait(1)
	            until not KitESP.Enabled
	        else
	            for _, v: RBXScriptConnection in Connections do
	                v:Disconnect()
	            end
	            table.clear(Connections)
	            table.clear(Reference)
	            Folder:ClearAllChildren()
	        end
	    end,
	    Tooltip = "ESP for certain kit related objects"
	})
	
	Background = KitESP:CreateToggle({
	    Name = "Background",
	    Function = function(Callback: boolean)
	        if Color.Object then
	            Color.Object.Visible = Callback
	        end
	        for _, v: BillboardGui in Reference do
	            v.ImageLabel.BackgroundTransparency = 1 - (Callback and Color.Opacity or 0)
	            v.Blur.Visible = Callback
	        end
	    end,
	    Default = true
	})
	Color = KitESP:CreateColorSlider({
	    Name = "Background Color",
	    DefaultValue = 0,
	    DefaultOpacity = 0.5,
	    Function = function(Hue: number, Sat: number, Val: number, Opacity: number)
	        for _, v: BillboardGui in Reference do
	            v.ImageLabel.BackgroundColor3 = Color3.fromHSV(Hue, Sat, Val)
	            v.ImageLabel.BackgroundTransparency = 1 - (Background.Enabled and Opacity or 0)
	        end
	    end,
	    Darker = true
	})
	Scale = KitESP:CreateSlider({
	    Name = "Scale",
	    Function = function(Val: number)
	        for _, v: BillboardGui in Reference do
	            v.Size = UDim2.fromOffset(36 * Val, 36 * Val)
	            v.ImageLabel.Size = UDim2.fromOffset(36 * Val, 36 * Val)
	            v.Blur.Size = UDim2.new(1, 89 * Val, 1, 52 * Val)
	            v.Blur.Position = UDim2.fromOffset(-48 * Val, -31 * Val)
	        end
	    end,
	    Default = 1,
	    Min = 0.1,
	    Max = 1.5,
	    Decimal = 10
	})
end)

Run(function()
	local NameTags
	local Targets
	local Color
	local Background
	local DisplayName
	local Health
	local Distance
	local Rank
	local Enchant
	local Equipment
	local Inventory
	local InventoryList
	local DrawingToggle
	local Scale
	local FontOption
	local Teammates
	local DistanceCheck
	local DistanceLimit
	local Strings, Sizes, Reference, Refreshes = {}, {}, {}, {}
	if vape.ThreadFix then
	    setthreadidentity(8)
	end
	
	local Folder: Folder = Instance.new("Folder")
	Folder.Parent = vape.gui
	local MethodUsed: string
	
	local function UpdateInventory(Ent, NameTag: TextLabel)
	    local Holder = Ent.Player and NameTag:FindFirstChild("Inventory")
	    local PlayerInventory = Holder and Store.inventories[Ent.Player]
	    if not PlayerInventory then return end
	
	    local Shown: number = 0
	    for _, v: any in PlayerInventory.items or {} do
	        if #InventoryList.ListEnabled > 0 and not table.find(InventoryList.ListEnabled, v.itemType) then continue end
	
	        Shown += 1
	        local Icon = Holder:FindFirstChild(tostring(Shown))
	        if not Icon then
	            Icon = Instance.new("ImageLabel")
	            Icon.Name = tostring(Shown)
	            Icon.Size = UDim2.fromOffset(24, 24)
	            Icon.BackgroundTransparency = 1
	            Icon.Parent = Holder
	            local Amount: TextLabel = Instance.new("TextLabel")
	            Amount.Name = "Amount"
	            Amount.Size = UDim2.fromOffset(23, 11)
	            Amount.Position = UDim2.fromOffset(0, 13)
	            Amount.BackgroundTransparency = 1
	            Amount.FontFace = NameTag.FontFace
	            Amount.TextSize = 11
	            Amount.TextColor3 = Color3.new(1, 1, 1)
	            Amount.TextStrokeColor3 = Color3.new()
	            Amount.TextStrokeTransparency = 0.4
	            Amount.TextXAlignment = Enum.TextXAlignment.Right
	            Amount.Parent = Icon
	        end
	
	        Icon.LayoutOrder = Shown
	        Icon.Visible = true
	        Icon.Image = Bedwars.getIcon(v, true)
	        Icon.Amount.Text = (v.amount or 1) > 1 and tostring(v.amount) or ""
	    end
	
	    for _, v: Instance in Holder:GetChildren() do
	        if v:IsA("ImageLabel") and tonumber(v.Name) > Shown then
	            v.Visible = false
	        end
	    end
	end
	
	local Added = {
	    Normal = function(Ent)
	        if not Targets.Players.Enabled and Ent.Player then return end
	        if not Targets.NPCs.Enabled and Ent.NPC then return end
	        if Teammates.Enabled and (not Ent.Targetable) and (not Ent.Friend) then return end
	
	        local NameTag: TextLabel = Instance.new("TextLabel")
	        Strings[Ent] = Ent.Player and `{Whitelist:tag(Ent.Player, true, true)}{DisplayName.Enabled and Ent.Player.DisplayName or Ent.Player.Name}` or Ent.Character.Name
	
	        if Health.Enabled then
	            local HealthColor: Color3 = Color3.fromHSV(math.clamp(Ent.Health / Ent.MaxHealth, 0, 1) / 2.5, 0.89, 0.75)
	            Strings[Ent] = `{Strings[Ent]} <font color="rgb({math.floor(HealthColor.R * 255)},{math.floor(HealthColor.G * 255)},{math.floor(HealthColor.B * 255)})">{math.round(Ent.Health)}</font>`
	        end
	
	        if Distance.Enabled then
	            Strings[Ent] = `<font color="rgb(85, 255, 85)">[</font><font color="rgb(255, 255, 255)">%s</font><font color="rgb(85, 255, 85)">]</font> {Strings[Ent]}`
	        end
	
	        if Equipment.Enabled then
	            for i: number, Slot: string in {"Hand", "Helmet", "Chestplate", "Boots", "Kit"} do
	                local Icon: ImageLabel = Instance.new("ImageLabel")
	                Icon.Name = Slot
	                Icon.Size = UDim2.fromOffset(30, 30)
	                Icon.Position = UDim2.fromOffset(-60 + (i * 30), -30)
	                Icon.BackgroundTransparency = 1
	                Icon.Image = ""
	                Icon.Parent = NameTag
	            end
	        end
	
	        if Inventory.Enabled and Ent.Player then
	            local Holder: Frame = Instance.new("Frame")
	            Holder.Name = "Inventory"
	            Holder.AnchorPoint = Vector2.new(0.5, 0)
	            Holder.AutomaticSize = Enum.AutomaticSize.X
	            Holder.BackgroundTransparency = 1
	            Holder.Position = UDim2.new(0.5, 0, 1, 2)
	            Holder.Size = UDim2.fromOffset(0, 24)
	            Holder.Parent = NameTag
	            local Layout: UIListLayout = Instance.new("UIListLayout")
	            Layout.FillDirection = Enum.FillDirection.Horizontal
	            Layout.HorizontalAlignment = Enum.HorizontalAlignment.Center
	            Layout.Padding = UDim.new(0, 2)
	            Layout.SortOrder = Enum.SortOrder.LayoutOrder
	            Layout.Parent = Holder
	        end
	
	        NameTag.TextSize = 14 * Scale.Value
	        NameTag.FontFace = FontOption.Value
	        local Size: Vector2 = GetFontBounds(RemoveTags(Strings[Ent]), NameTag.TextSize, NameTag.FontFace)
	
	        task.spawn(function()
	            if Rank.Enabled and Ent.Player then
	                local Icon: ImageLabel = Instance.new("ImageLabel")
	                Icon.Name = "RankIcon"
	                Icon.Size = UDim2.fromOffset(30, 30)
	                Icon.Position = UDim2.fromOffset(Size.X + 10, -4)
	                Icon.BackgroundTransparency = 1
	                Icon.Image = Store.rank[Ent.Player]:async() and Bedwars.RankMeta[Store.rank[Ent.Player]:async()].image or ""
	                Icon.Parent = NameTag
	            end
	        end)
	
	        task.spawn(function()
	            if Enchant.Enabled and Ent.Player then
	                local Icon: ImageLabel = Instance.new("ImageLabel")
	                Icon.Name = "EnchantIcon"
	                Icon.Size = UDim2.fromOffset(30, 30)
	                Icon.Position = UDim2.fromOffset(-30, -4)
	                Icon.BackgroundTransparency = 1
	                Icon.Image = Store.enchants[Ent.Player]:async() or ""
	                Icon.Parent = NameTag
	            end
	        end)
	
	        NameTag.Name = Ent.Player and Ent.Player.Name or Ent.Character.Name
	        NameTag.Size = UDim2.fromOffset(Size.X + 8, Size.Y + 7)
	        NameTag.AnchorPoint = Vector2.new(0.5, 1)
	        NameTag.BackgroundColor3 = Color3.new()
	        NameTag.BackgroundTransparency = Background.Value
	        NameTag.BorderSizePixel = 0
	        NameTag.Visible = false
	        NameTag.Text = Distance.Enabled and Entity.isAlive and string.format(Strings[Ent], math.floor((Entity.character.RootPart.Position - Ent.RootPart.Position).Magnitude)) or Strings[Ent]
	        NameTag.TextColor3 = Entity.getEntityColor(Ent) or Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
	        NameTag.RichText = true
	
	        NameTag.Parent = Folder
	        Reference[Ent] = NameTag
	    end,
	    Drawing = function(Ent)
	        if not Targets.Players.Enabled and Ent.Player then return end
	        if not Targets.NPCs.Enabled and Ent.NPC then return end
	        if Teammates.Enabled and (not Ent.Targetable) and (not Ent.Friend) then return end
	
	        local NameTag = {}
	        NameTag.BG = Drawing.new("Square")
	        NameTag.BG.Filled = true
	        NameTag.BG.Transparency = 1 - Background.Value
	        NameTag.BG.Color = Color3.new()
	        NameTag.BG.ZIndex = 1
	        NameTag.Text = Drawing.new("Text")
	        NameTag.Text.Size = 15 * Scale.Value
	        NameTag.Text.Font = 0
	        NameTag.Text.ZIndex = 2
	        Strings[Ent] = Ent.Player and `{Whitelist:tag(Ent.Player, true)}{DisplayName.Enabled and Ent.Player.DisplayName or Ent.Player.Name}` or Ent.Character.Name
	
	        if Health.Enabled then
	            Strings[Ent] = `{Strings[Ent]} {math.round(Ent.Health)}`
	        end
	
	        if Distance.Enabled then
	            Strings[Ent] = `[%s] {Strings[Ent]}`
	        end
	
	        NameTag.Text.Text = Strings[Ent]
	        NameTag.Text.Color = Entity.getEntityColor(Ent) or Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
	        NameTag.BG.Size = Vector2.new(NameTag.Text.TextBounds.X + 8, NameTag.Text.TextBounds.Y + 7)
	        Reference[Ent] = NameTag
	    end
	}
	
	local Removed = {
	    Normal = function(Ent)
	        local NameTag = Reference[Ent]
	        if NameTag then
	            Reference[Ent] = nil
	            Strings[Ent] = nil
	            Sizes[Ent] = nil
	            Refreshes[Ent] = nil
	            NameTag:Destroy()
	        end
	    end,
	    Drawing = function(Ent)
	        local NameTag = Reference[Ent]
	        if NameTag then
	            Reference[Ent] = nil
	            Strings[Ent] = nil
	            Sizes[Ent] = nil
	            for _, Object: any in NameTag do
	                pcall(function()
	                    Object.Visible = false
	                    Object:Remove()
	                end)
	            end
	        end
	    end
	}
	
	local Updated = {
	    Normal = function(Ent)
	        local NameTag = Reference[Ent]
	        if NameTag then
	            Sizes[Ent] = nil
	            Strings[Ent] = Ent.Player and `{Whitelist:tag(Ent.Player, true, true)}{DisplayName.Enabled and Ent.Player.DisplayName or Ent.Player.Name}` or Ent.Character.Name
	
	            if Health.Enabled then
	                local HealthColor: Color3 = Color3.fromHSV(math.clamp(Ent.Health / Ent.MaxHealth, 0, 1) / 2.5, 0.89, 0.75)
	                Strings[Ent] = `{Strings[Ent]} <font color="rgb({math.floor(HealthColor.R * 255)},{math.floor(HealthColor.G * 255)},{math.floor(HealthColor.B * 255)})">{math.round(Ent.Health)}</font>`
	            end
	
	            if Distance.Enabled then
	                Strings[Ent] = `<font color="rgb(85, 255, 85)">[</font><font color="rgb(255, 255, 255)">%s</font><font color="rgb(85, 255, 85)">]</font> {Strings[Ent]}`
	            end
	
	            if Equipment.Enabled and Store.inventories[Ent.Player] then
	                local Kit: string? = Ent.Player:GetAttribute("PlayingAsKits")
	                local KitMeta = Kit and Kit ~= "none" and Bedwars.BedwarsKitMeta[Kit]
	                local PlayerInventory = Store.inventories[Ent.Player]
	                local Armor = {}
	                for _, v: any in PlayerInventory.armor or {} do
	                    local ItemMeta = typeof(v) == "table" and Bedwars.ItemMeta[v.itemType]
	                    if ItemMeta and ItemMeta.armor then
	                        Armor[ItemMeta.armor.slot] = v
	                    end
	                end
	
	                NameTag.Hand.Image = Bedwars.getIcon(PlayerInventory.hand or {itemType = ""}, true)
	                NameTag.Helmet.Image = Bedwars.getIcon(Armor[0] or {itemType = ""}, true)
	                NameTag.Chestplate.Image = Bedwars.getIcon(Armor[1] or {itemType = ""}, true)
	                NameTag.Boots.Image = Bedwars.getIcon(Armor[2] or {itemType = ""}, true)
	                NameTag.Kit.Image = KitMeta and KitMeta.renderImage or ""
	            end
	
	            if Inventory.Enabled then
	                UpdateInventory(Ent, NameTag)
	            end
	
	            if Enchant.Enabled and NameTag:FindFirstChild("EnchantIcon") then
	                NameTag.EnchantIcon.Image = Store.enchants[Ent.Player]:async() or ""
	            end
	
	            local Text: string = Distance.Enabled and Entity.isAlive and string.format(Strings[Ent], math.floor((Entity.character.RootPart.Position - Ent.RootPart.Position).Magnitude)) or Strings[Ent]
	            local Size: Vector2 = GetFontBounds(RemoveTags(Text), NameTag.TextSize, NameTag.FontFace)
	            NameTag.Size = UDim2.fromOffset(Size.X + 8, Size.Y + 7)
	            NameTag.Text = Text
	        end
	    end,
	    Drawing = function(Ent)
	        local NameTag = Reference[Ent]
	        if NameTag then
	            Sizes[Ent] = nil
	            Strings[Ent] = Ent.Player and `{Whitelist:tag(Ent.Player, true)}{DisplayName.Enabled and Ent.Player.DisplayName or Ent.Player.Name}` or Ent.Character.Name
	
	            if Health.Enabled then
	                Strings[Ent] = `{Strings[Ent]} {math.round(Ent.Health)}`
	            end
	
	            if Distance.Enabled then
	                Strings[Ent] = `[%s] {Strings[Ent]}`
	                NameTag.Text.Text = Entity.isAlive and string.format(Strings[Ent], math.floor((Entity.character.RootPart.Position - Ent.RootPart.Position).Magnitude)) or Strings[Ent]
	            else
	                NameTag.Text.Text = Strings[Ent]
	            end
	
	            NameTag.BG.Size = Vector2.new(NameTag.Text.TextBounds.X + 8, NameTag.Text.TextBounds.Y + 7)
	            NameTag.Text.Color = Entity.getEntityColor(Ent) or Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
	        end
	    end
	}
	
	local ColorFunc = {
	    Normal = function(Hue: number, Sat: number, Val: number)
	        local DefaultColor: Color3 = Color3.fromHSV(Hue, Sat, Val)
	        for Ent: any, v: TextLabel in Reference do
	            v.TextColor3 = Entity.getEntityColor(Ent) or DefaultColor
	        end
	    end,
	    Drawing = function(Hue: number, Sat: number, Val: number)
	        local DefaultColor: Color3 = Color3.fromHSV(Hue, Sat, Val)
	        for Ent: any, v: any in Reference do
	            v.Text.Color = Entity.getEntityColor(Ent) or DefaultColor
	        end
	    end
	}
	
	local Loop = {
	    Normal = function()
	        if vape.ThreadFix then
	            setthreadidentity(8)
	        end
	
	        local LocalPosition = Entity.isAlive and Entity.character.RootPart.Position
	
	        for Ent: any, v: TextLabel in Reference do
	            local RootPosition: Vector3 = Ent.RootPart.Position
	
	            if DistanceCheck.Enabled then
	                local EntityDistance: number = LocalPosition and (LocalPosition - RootPosition).Magnitude or math.huge
	                if EntityDistance < DistanceLimit.ValueMin or EntityDistance > DistanceLimit.ValueMax then
	                    v.Visible = false
	                    continue
	                end
	            end
	
	            local HeadPos, HeadVisible = Camera:WorldToViewportPoint(RootPosition + Vector3.new(0, Ent.HipHeight + 1, 0))
	            v.Visible = HeadVisible
	            if not HeadVisible then
	                continue
	            end
	
	            if Inventory.Enabled and Ent.Player and (Refreshes[Ent] or 0) < tick() then
	                Refreshes[Ent] = tick() + 0.5
	                Store.inventories[Ent.Player] = Bedwars.getInventory(Ent.Player)
	                UpdateInventory(Ent, v)
	            end
	
	            if Distance.Enabled then
	                local RoundedDistance: number = LocalPosition and math.floor((LocalPosition - RootPosition).Magnitude) or 0
	                if Sizes[Ent] ~= RoundedDistance then
	                    v.Text = string.format(Strings[Ent], RoundedDistance)
	                    local Size: Vector2 = GetFontBounds(RemoveTags(v.Text), v.TextSize, v.FontFace)
	                    v.Size = UDim2.fromOffset(Size.X + 8, Size.Y + 7)
	                    Sizes[Ent] = RoundedDistance
	                end
	            end
	            v.Position = UDim2.fromOffset(HeadPos.X, HeadPos.Y)
	        end
	    end,
	    Drawing = function()
	        if vape.ThreadFix then
	            setthreadidentity(8)
	        end
	
	        local LocalPosition = Entity.isAlive and Entity.character.RootPart.Position
	
	        for Ent: any, v: any in Reference do
	            local RootPosition: Vector3 = Ent.RootPart.Position
	
	            if DistanceCheck.Enabled then
	                local EntityDistance: number = LocalPosition and (LocalPosition - RootPosition).Magnitude or math.huge
	                if EntityDistance < DistanceLimit.ValueMin or EntityDistance > DistanceLimit.ValueMax then
	                    v.Text.Visible = false
	                    v.BG.Visible = false
	                    continue
	                end
	            end
	
	            local HeadPos, HeadVisible = Camera:WorldToViewportPoint(RootPosition + Vector3.new(0, Ent.HipHeight + 1, 0))
	            v.Text.Visible = HeadVisible
	            v.BG.Visible = HeadVisible
	            if not HeadVisible then
	                continue
	            end
	
	            if Distance.Enabled then
	                local RoundedDistance: number = LocalPosition and math.floor((LocalPosition - RootPosition).Magnitude) or 0
	                if Sizes[Ent] ~= RoundedDistance then
	                    v.Text.Text = string.format(Strings[Ent], RoundedDistance)
	                    v.BG.Size = Vector2.new(v.Text.TextBounds.X + 8, v.Text.TextBounds.Y + 7)
	                    Sizes[Ent] = RoundedDistance
	                end
	            end
	            v.BG.Position = Vector2.new(HeadPos.X - (v.BG.Size.X / 2), HeadPos.Y - v.BG.Size.Y)
	            v.Text.Position = v.BG.Position + Vector2.new(4, 3)
	        end
	    end
	}
	
	NameTags = vape.Categories.Render:CreateModule({
	    Name = "NameTags",
	    Function = function(Callback: boolean)
	        if Callback then
	            MethodUsed = DrawingToggle.Enabled and "Drawing" or "Normal"
	            if Removed[MethodUsed] then
	                NameTags:Clean(Entity.Events.EntityRemoved:Connect(Removed[MethodUsed]))
	            end
	            if Added[MethodUsed] then
	                for _, v: any in Entity.List do
	                    if Reference[v] then
	                        Removed[MethodUsed](v)
	                    end
	                    Added[MethodUsed](v)
	                end
	                NameTags:Clean(Entity.Events.EntityAdded:Connect(function(Ent)
	                    if Reference[Ent] then
	                        Removed[MethodUsed](Ent)
	                    end
	                    Added[MethodUsed](Ent)
	                end))
	            end
	            if Updated[MethodUsed] then
	                NameTags:Clean(Entity.Events.EntityUpdated:Connect(Updated[MethodUsed]))
	                for _, v: any in Entity.List do
	                    Updated[MethodUsed](v)
	                end
	            end
	            if ColorFunc[MethodUsed] then
	                NameTags:Clean(vape.Categories.Friends.ColorUpdate.Event:Connect(function()
	                    ColorFunc[MethodUsed](Color.Hue, Color.Sat, Color.Value)
	                end))
	            end
	            if Loop[MethodUsed] then
	                NameTags:Clean(RunService.RenderStepped:Connect(Loop[MethodUsed]))
	            end
	        else
	            if Removed[MethodUsed] then
	                for Ent: any in Reference do
	                    Removed[MethodUsed](Ent)
	                end
	            end
	        end
	    end,
	    Tooltip = "Renders nametags on entities through walls."
	})
	
	Targets = NameTags:CreateTargets({
