Run(function()
	local MemoryFixer
	local Sync
	local Interval
	local Notify
	local Signals: {string} = {"Heartbeat", "PostSimulation", "PreAnimation", "PreRender", "PreSimulation", "RenderStepped", "Stepped"}
	
	local function Clean(): number
	    if not getconnections or not getfunctionhash or not isexecutorclosure then
	        return 0
	    end
	
	    local Removed, Seen = 0, {}
	    for _, v: string in Signals do
	        for _, Connection: any in getconnections(RunService[v]) do
	            if Connection.Function and not Connection.ForeignState and isexecutorclosure(Connection.Function) then
	                local Hash: string = `{v}{getfunctionhash(Connection.Function)}`
	                if Seen[Hash] then
	                    Connection:Disconnect()
	                    Removed += 1
	                else
	                    Seen[Hash] = true
	                end
	            end
	        end
	    end
	
	    if Sync.Enabled then
	        for _, v: any in Bedwars.SyncEvents do
	            if typeof(v) == "table" and typeof(v.entries) == "table" then
	                table.clear(Seen)
	                for i: number, Entry: any in v.entries do
	                    local Callback = Entry.callbackInfo and Entry.callbackInfo.callback
	                    if Callback and isexecutorclosure(Callback) then
	                        local Hash: string = getfunctionhash(Callback)
	                        if Seen[Hash] then
	                            v.entries[i] = nil
	                            v.isSorted = false
	                            Removed += 1
	                        else
	                            Seen[Hash] = true
	                        end
	                    end
	                end
	            end
	        end
	    end
	
	    return Removed
	end
	
	MemoryFixer = vape.Categories.Utility:CreateModule({
	    Name = "MemoryFixer",
	    Function = function(Callback: boolean)
	        if Callback then
	            task.spawn(function()
	                repeat
	                    local Removed: number = Clean()
	                    if Notify.Enabled and Removed > 0 then
	                        SendNotification("MemoryFixer", `Dropped {Removed} leftover connection{Removed == 1 and "" or "s"}`, 5)
	                    end
	                    task.wait(Interval.Value)
	                until not MemoryFixer.Enabled
	            end)
	        end
	    end,
	    Tooltip = "Drops the duplicate loops and listeners an older injection left connected"
	})
	
	Sync = MemoryFixer:CreateToggle({
	    Name = "Sync events",
	    Default = true,
	    Tooltip = "Also prunes duplicate bedwars sync event listeners, the ones that survive a reinject"
	})
	Interval = MemoryFixer:CreateSlider({
	    Name = "Interval",
	    Min = 5,
	    Max = 300,
	    Default = 30,
	    Suffix = "seconds"
	})
	Notify = MemoryFixer:CreateToggle({
	    Name = "Notify",
	    Default = true,
	    Tooltip = "Tells you how many it dropped"
	})
	MemoryFixer:CreateButton({
	    Name = "Clean now",
	    Function = function()
	        local Removed: number = Clean()
	        SendNotification("MemoryFixer", `Dropped {Removed} leftover connection{Removed == 1 and "" or "s"}`, 5)
	    end
	})
end)

