Run(function()
	local AutoBuilder
	local Animation
	local Blacklist
	local BedCheck
	local Limit
	
	local function GetBed(Position: Vector3): BasePart?
	    local Bed, LastMagnitude = nil, math.huge
	    for _, v: BasePart in CollectionService:GetTagged("bed") do
	        local Magnitude: number = (Position - v.Position).Magnitude
	        if Magnitude < LastMagnitude and v:GetAttribute(`Team{LocalPlayer:GetAttribute("Team") or -1}NoBreak`) then
	            Bed, LastMagnitude = v, Magnitude
	        end
	    end
	    return Bed
	end
	
	AutoBuilder = vape.Categories.Kits:CreateModule({
	    Name = "AutoBuilder",
	    Function = function(Callback: boolean)
	        if Callback then
	            repeat
	                task.wait()
	            until Store.matchState ~= 0 and Store.equippedKit == "builder" or not AutoBuilder.Enabled
	            if not AutoBuilder.Enabled then
	                return
	            end
	
	            local Blocks: {BasePart} = Collection("block", AutoBuilder, function(List: {BasePart}, Block: BasePart)
	                task.delay(0, function()
	                    if not Block:GetAttribute("NoBreak") and Block:GetAttribute("PlacedByUserId") then
	                        table.insert(List, Block)
	                    end
	                end)
	            end)
	
	            repeat
	                if Entity.isAlive and (not Limit.Enabled and GetItem("hammer") or Limit.Enabled and Store.hand.tool and Store.hand.tool.Name == "hammer") then
	                    local Bed: BasePart? = GetBed(Entity.character.RootPart.Position)
	
	                    for _, v: BasePart in Blocks do
	                        if not BedCheck.Enabled or Bed and (Bed.Position - v.Position).Magnitude <= 30 then
	                            local BlockName: string = v.Name:find("wool_") and "wool" or v.Name
	                            if not table.find(Blacklist.ListEnabled, BlockName) and not v:FindFirstChild("BuilderFortify") then
	                                Bedwars.Handler:Get("FortifyBlock"):Fire("SendToServer", ({GetPlacedBlock(v.Position)})[2])
	
	                                if Animation.Enabled then
	                                    Bedwars.GameAnimationUtil:playAnimation(LocalPlayer, Bedwars.GameAnimationUtil:getAssetId(Bedwars.AnimationType.BUILDER_HAMMER_HIT), {
	                                        fadeInTime = 0.02
	                                    })
	                                    Bedwars.AudioManager:playAudio(Bedwars.SoundList.FORTIFY_BLOCK, {
	                                        position = Entity.character.RootPart.Position
	                                    })
	                                end
	                            end
	                        end
	                    end
	                end
	                task.wait(0.1)
	            until not AutoBuilder.Enabled
	        end
	    end,
	    Tooltip = "Automatically fortifies your blocks with the builder hammer"
	})
	
	BedCheck = AutoBuilder:CreateToggle({
	    Name = "Bed Check",
	    Tooltip = "Checks if the block is near your bed"
	})
	Animation = AutoBuilder:CreateToggle({
	    Name = "Animation",
	    Default = true,
	    Tooltip = "Plays builder visuals (sfx and anim)"
	})
	Limit = AutoBuilder:CreateToggle({
	    Name = "Limit to items",
	    Default = true
	})
	Blacklist = AutoBuilder:CreateTextList({
	    Name = "Blacklists",
	    Placeholder = "block",
	    Default = {"cannon", "wool"}
	})
end)

Run(function()
	local AutoCaitlyn
	local Mode
	local Range
	local MinHP
	local TargetPriorities
	local ActiveSession
	
	local function GetValidTargets(WallCheck: boolean)
	    local Targets = {}
	    for _, v: any in Entity.AllPosition({
	        Part = "RootPart",
	        Players = true,
	        Range = Range.Value,
	        Wallcheck = WallCheck
	    }) do
	        if not (v.Player.Team and v.Player.Team.Name == "Spectators") then
	            Targets[v.Player] = v
	            Targets[v.Character] = v
	        end
	    end
	    return Targets
	end
	
	local function GetScore(Session, Contract, Targets)
	    local Ent = Targets[Contract.target]
	    if not Ent then
	        return nil
	    end
	
	    local Health: number = Ent.Humanoid.Health
	    local Distance: number = (Entity.character.RootPart.Position - Ent.RootPart.Position).Magnitude
	    local Score: number = 30 + ((tonumber(Contract.rewardValue) or 0) * 35)
	    Score += (1 - math.clamp(Health / math.max(Ent.Humanoid.MaxHealth, 1), 0, 1)) * 35
	    Score += math.max(1 - (Distance / Range.Value), 0) * 20
	
	    if Health <= MinHP.Value then
	        Score += 20
	    end
	    if (Session.threats[Ent.Player] or 0) > tick() then
	        Score += 30
	    end
	    if Ent.Character:GetAttribute("BleedSource") == LocalPlayer.UserId then
	        Score += 25
	    end
	    local Success, Team = pcall(Bedwars.TeamController.getPlayerTeam, Bedwars.TeamController, Ent.Player)
	    local TeamId = Success and Team and Team.id or Ent.Player:GetAttribute("Team")
	    local Bed = true
	    if TeamId ~= nil then
	        local Cached = Session.beds[TeamId]
	        if Cached and Cached[2] > tick() then
	            Bed = Cached[1]
	        else
	            Success, Team = pcall(Bedwars.BedwarsController.getTeamBed, Bedwars.BedwarsController, TeamId)
	            Bed = not Success or Team and Team.Parent
	            Session.beds[TeamId] = {Bed, tick() + 1}
	        end
	    end
	
	    if not Bed then
	        Score += 20
	    end
	
	    local Reward = Contract.rewardExplanation
	    if type(Reward) == "table" then
	        Score += (Reward.assassin and 10 or 0) + (Reward.kitClass and 8 or 0) + (Reward.gear and 6 or 0)
	    end
	    return Score, Ent
	end
	
	local function GetPriorityContract(Session, Contracts)
	    local Bounty: boolean = false
	    for _, v: any in Contracts do
	        if v.rewardValue or v.rewardUpgrade then
	            Bounty = true
	            break
	        end
	    end
	    if not Bounty then
	        return nil, false
	    end
	
	    local Targets = GetValidTargets(true)
	    local Current, CurrentScore
	    if Session.priorityId then
	        for _, v: any in Contracts do
	            if v.id == Session.priorityId then
	                Current, CurrentScore = v, GetScore(Session, v, Targets)
	                break
	            end
	        end
	    end
	
	    local Best, BestScore
	    for _, v: any in Contracts do
	        local Score: number? = GetScore(Session, v, Targets)
	        if Score and (not BestScore or Score > BestScore) then
	            Best, BestScore = v, Score
	        end
	    end
	
	    if Current and CurrentScore and Best ~= Current and BestScore < CurrentScore + 15 then
	        Best = Current
	    end
	
	    Session.priorityId = Best and Best.id or nil
	    return Best, true
	end
	
	local function GetNormalContract(Session, Contracts)
	    local Hit = Session.lastHit
	    if Hit and Hit[2] > tick() then
	        local Ent = GetValidTargets(false)[Hit[1].Player]
	        if Ent == Hit[1] then
	            if Mode.Value == "On Low" and Ent.Humanoid.Health >= MinHP.Value then
	                return nil
	            end
	            for _, v: any in Contracts do
	                if v.target == Ent.Player or v.target and v.target.Name == Ent.Player.Name then
	                    return v
	                end
	            end
	            return nil
	        end
	    end
	
	    Session.lastHit = nil
	    return nil
	end
	
	local function UpdateCaitlyn(Session)
	    if not Entity.isAlive or Store.matchState ~= 1 or Store.equippedKit ~= "blood_assassin" then
	        Session.lastHit = nil
	        Session.pendingId = nil
	        Session.priorityId = nil
	        return
	    end
	
	    local Kit = Bedwars.Store:getState().Kit
	    if not Kit or Kit.activeContract then
	        Session.pendingId = nil
	        Session.priorityId = Kit and Kit.activeContract and Kit.activeContract.id or nil
	        return
	    end
	
	    if Session.pendingId and Session.pendingUntil > tick() then
	        return
	    end
	    Session.pendingId = nil
	
	    local Contracts = Kit.availableContracts
	    if not Contracts or #Contracts == 0 then
	        return
	    end
	
	    local Contract
	    if TargetPriorities.Enabled then
	        local Available
	        Contract, Available = GetPriorityContract(Session, Contracts)
	        if not Available then
	            Contract = GetNormalContract(Session, Contracts)
	        end
	    else
	        Session.priorityId = nil
	        Contract = GetNormalContract(Session, Contracts)
	    end
	    if Contract and not (Session.pendingId == Contract.id and Session.pendingUntil > tick()) then
	        Bedwars.Handler:Get("BloodAssassinSelectContract"):Fire("SendToServer", {
	            contractId = Contract.id
	        })
	        Session.pendingId = Contract.id
	        Session.pendingUntil = tick() + 1
	    end
	end
	
	AutoCaitlyn = vape.Categories.Kits:CreateModule({
	    Name = "AutoCaitlyn",
	    Function = function(Callback: boolean)
	        if Callback then
	            local Session = {
	                beds = {},
	                nextUpdate = 0,
	                pendingUntil = 0,
	                threats = {}
	            }
	            ActiveSession = Session
	
	            AutoCaitlyn:Clean(VapeEvents.EntityDamageEvent.Event:Connect(function(DamageTable)
	                if ActiveSession ~= Session then
	                    return
	                end
	
	                local Source = (typeof(DamageTable.fromEntity) == "Instance" and Entity.getEntity(DamageTable.fromEntity) or nil)
	                if DamageTable.entityInstance == LocalPlayer.Character and Source and Source.Player then
	                    Session.threats[Source.Player] = tick() + 3
	                elseif DamageTable.fromEntity == LocalPlayer.Character or DamageTable.fromEntity == LocalPlayer then
	                    local Victim = (typeof(DamageTable.entityInstance) == "Instance" and Entity.getEntity(DamageTable.entityInstance) or nil)
	                    if Victim then
	                        Session.lastHit = {Victim, tick() + 1}
	                    end
	                end
	            end))
	
	            AutoCaitlyn:Clean(VapeEvents.BedwarsBedBreak.Event:Connect(function()
	                table.clear(Session.beds)
	            end))
	
	            AutoCaitlyn:Clean(Entity.Events.LocalAdded:Connect(function()
	                Session.lastHit = nil
	                Session.pendingId = nil
	            end))
	
	            AutoCaitlyn:Clean(Entity.Events.LocalRemoved:Connect(function()
	                Session.lastHit = nil
	                Session.pendingId = nil
	                Session.priorityId = nil
	            end))
	
	            repeat
	                if tick() >= Session.nextUpdate then
	                    Session.nextUpdate = tick() + 0.2
	                    UpdateCaitlyn(Session)
	                end
	                task.wait(0.05)
	            until not AutoCaitlyn.Enabled or ActiveSession ~= Session
	
	            if ActiveSession == Session then
	                ActiveSession = nil
	            end
	        else
	            ActiveSession = nil
	        end
	    end,
	    Tooltip = "Automatically assigns a player's contract when a specific action happens"
	})
	
	Mode = AutoCaitlyn:CreateDropdown({
	    Name = "Contract mode",
	    List = {"On Hit", "On Low"},
	    Function = function(Val: string)
	        if MinHP then
	            MinHP.Object.Visible = Val == "On Low"
	        end
	    end,
	    Default = "On Low",
	    Tooltip = "On Hit - Contracts them whenever u start hitting them\nOn Low - When they're low"
	})
	MinHP = AutoCaitlyn:CreateSlider({
	    Name = "Minimum Health",
	    Tooltip = "How low they have to be before contracting",
	    Min = 1,
	    Max = 100,
	    Default = 30,
	    Darker = true,
	    Visible = false
	})
	Range = AutoCaitlyn:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 50,
	    Default = 50,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end
	})
	TargetPriorities = AutoCaitlyn:CreateToggle({
	    Name = "Target Priorities",
	    Function = function()
	        if ActiveSession then
	            ActiveSession.priorityId = nil
	        end
	    end
	})
end)

Run(function()
	local AutoCard
	local Range
	local Delay
	local NextThrow: number = 0
	
	AutoCard = vape.Categories.Kits:CreateModule({
	    Name = "AutoCard",
	    Function = function(Callback: boolean)
	        if Callback then
	            NextThrow = 0
	
	            repeat
	                if Entity.isAlive and Store.equippedKit == "card" and tick() >= NextThrow and Bedwars.AbilityController:canUseAbility("CARD_THROW", {disableBlockedAbilityAlert = true}) then
	                    local Target = Entity.EntityPosition({
	                        Origin = Entity.character.RootPart.Position,
	                        Range = Range.Value,
	                        Part = "RootPart",
	                        Players = true,
	                        Wallcheck = true
	                    })
	
	                    if Target then
	                        NextThrow = tick() + Delay.Value
	                        Bedwars.AbilityController:useAbility("CARD_THROW")
	                    end
	                end
	                task.wait(0.1)
	            until not AutoCard.Enabled
	        end
	    end,
	    Tooltip = "Automatically throws Fortuna cards at whoever is near you"
	})
	
	Range = AutoCard:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 100,
	    Default = 60,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end
	})
	Delay = AutoCard:CreateSlider({
	    Name = "Delay",
	    Min = 0.1,
	    Max = 3,
	    Default = 0.4,
	    Decimal = 10,
	    Suffix = function(Val: number)
	        return Val <= 1 and "sec" or "secs"
	    end
	})
end)

Run(function()
	local AutoCogsworth
	local Targets
	local Collect
	local Steal
	local Range
	local Delay
	local Overclock
	local OverclockRange
	local NextCollect: number = 0
	local NextOverclock: number = 0
	
	local function GetBots()
	    local Controller = Bedwars.GatherBotBasicController
	    return Controller and Controller.gatherBotMap or {}
	end
	
	AutoCogsworth = vape.Categories.Kits:CreateModule({
	    Name = "AutoCogsworth",
	    Function = function(Callback: boolean)
	        if Callback then
	            NextCollect = 0
	            NextOverclock = 0
	
	            repeat
	                if Entity.isAlive then
	                    local Origin: Vector3 = Entity.character.RootPart.Position
	
	                    if Collect.Enabled and tick() >= NextCollect then
	                        for Bot: Model in GetBots() do
	                            if not Bot.Parent then
	                                continue
	                            end
	                            local Owner = Bot:GetAttribute("PlacedByUserId")
	                            if not Steal.Enabled and Owner ~= LocalPlayer.UserId then
	                                continue
	                            end
	                            if (Bot:GetAttribute("HeldItemAmount") or 0) <= 0 then
	                                continue
	                            end
	                            if (Bot:GetPivot().Position - Origin).Magnitude > Range.Value then
	                                continue
	                            end
	
	                            Bedwars.Handler:Get("GatherBotCollectItems"):Fire("SendToServer", {
	                                player = LocalPlayer,
	                                gatherBot = Bot
	                            })
	                            NextCollect = tick() + Delay.Value
	                            break
	                        end
	                    end
	
	                    if Overclock.Enabled and Store.equippedKit == "steam_engineer" and tick() >= NextOverclock and Bedwars.AbilityController:canUseAbility("STEAM_ENGINEER_OVERCLOCK", {disableBlockedAbilityAlert = true}) then
	                        local Found: boolean = #Entity.AllPosition({
	                            Range = OverclockRange.Value,
	                            Part = "RootPart",
	                            Players = Targets.Players.Enabled,
	                            NPCs = Targets.NPCs.Enabled
	                        }) > 0
	
	                        if Found then
	                            NextOverclock = tick() + 1
	                            Bedwars.AbilityController:useAbility("STEAM_ENGINEER_OVERCLOCK")
	                        end
	                    end
	                end
	                task.wait(0.1)
	            until not AutoCogsworth.Enabled
	        end
	    end,
	    Tooltip = "Empties gather bots from across the map and overclocks when a fight starts"
	})
	
	Targets = AutoCogsworth:CreateTargets({
	    Players = true,
	    NPCs = true
	})
	Collect = AutoCogsworth:CreateToggle({
	    Name = "Collect bots",
	    Default = true,
	    Tooltip = "The games own collect prompt stops at 10 studs, the server never checks it"
	})
	Steal = AutoCogsworth:CreateToggle({
	    Name = "Steal enemy bots",
	    Tooltip = "Also empties gather bots that somebody else placed"
	})
	Range = AutoCogsworth:CreateSlider({
	    Name = "Range",
	    Min = 5,
	    Max = 500,
	    Default = 250,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end
	})
	Delay = AutoCogsworth:CreateSlider({
	    Name = "Delay",
	    Min = 0.1,
	    Max = 3,
	    Default = 0.3,
	    Decimal = 100,
	    Suffix = function(Val: number)
	        return Val <= 1 and "sec" or "secs"
	    end
	})
	Overclock = AutoCogsworth:CreateToggle({
	    Name = "Overclock",
	    Default = true,
	    Function = function(Callback: boolean)
	        if OverclockRange then
	            OverclockRange.Object.Visible = Callback
	        end
	    end
	})
	OverclockRange = AutoCogsworth:CreateSlider({
	    Name = "Overclock range",
	    Min = 1,
	    Max = 60,
	    Default = 25,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end
	})
end)

Run(function()
	local AutoCrocowolf
	local Range
	local Targets
	
	AutoCrocowolf = vape.Categories.Kits:CreateModule({
	    Name = "AutoCrocowolf",
	    Function = function(Callback: boolean)
	        if Callback then
	            repeat
	                if Entity.isAlive and Store.equippedKit == "beast" and Bedwars.AbilityController:canUseAbility("beast_form", {disableBlockedAbilityAlert = true}) then
	                    local Origin: Vector3 = Entity.character.RootPart.Position
	                    local Found: number = 0
	                    for _, v: any in Entity.List do
	                        if v.Targetable and (v.RootPart.Position - Origin).Magnitude <= Range.Value then
	                            Found += 1
	                        end
	                    end
	
	                    if Found >= Targets.Value then
	                        Bedwars.AbilityController:useAbility("beast_form")
	                    end
	                end
	                task.wait(0.1)
	            until not AutoCrocowolf.Enabled
