Run(function()
	local AutoNoelle
	local Notify
	local FrostySlime
	local HealSlime
	local StickySlime
	local VoidSlime
	local Limit
	
	local function GetSlimes()
	    local Slimes = {}
	    local Folder: Instance? = workspace:FindFirstChild("SlimeModelFolder")
	    for _, v: Instance in Folder and Folder:GetChildren() or {} do
	        local Data = v:FindFirstChild("SlimeData")
	        Data = Data and Data.Value
	
	        if Data and Data.Tamer.Value == LocalPlayer.UserId then
	            table.insert(Slimes, {
	                Data = Data,
	                RootPart = v,
	                Name = v.Name:gsub(`_{LocalPlayer.Name}`, ""):gsub("Slime", " Slime")
	            })
	        end
	    end
	    return Slimes
	end
	
	local function GetPlayer(Name: string)
	    for _, v: Player in Players:GetPlayers() do
	        if `{v.DisplayName} ({v.Name})` == Name then
	            return v
	        end
	    end
	    return
	end
	
	AutoNoelle = vape.Categories.Kits:CreateModule({
	    Name = "AutoNoelle",
	    Function = function(Callback: boolean)
	        if Callback then
	            repeat
	                if Entity.isAlive and (not Limit.Enabled or Store.hand.tool and Store.hand.tool.Name == "slime_tamer_flute") then
	                    for _, v: any in GetSlimes() do
	                        local Dropdown = AutoNoelle.Options[`{v.Name} Target`]
	                        local TargetPlayer: Player? = Dropdown and GetPlayer(Dropdown.Value)
	                        if TargetPlayer and v.Data.Following.Value ~= TargetPlayer.UserId then
	                            Bedwars.Handler:Get("RequestMoveSlime"):Fire("CallServerAsync", {
	                                slimeId = v.Data:GetAttribute("Id"),
	                                targetPlayerUserId = TargetPlayer.UserId
	                            }):andThen(function(Success: boolean)
	                                if Success then
	                                    v.Data.Following.Value = TargetPlayer.UserId
	
	                                    if Notify.Enabled then
	                                        SendNotification("AutoNoelle", `Directed {v.Name} to {TargetPlayer.DisplayName} ({TargetPlayer.Name})`, 5, "info")
	                                    end
	                                end
	                            end)
	                        end
	                    end
	                end
	                task.wait(0.5)
	            until not AutoNoelle.Enabled
	        end
	    end,
	    Tooltip = "Automatically directs the slimes to the selected player's"
	})
	
	local Friends: {string} = {"None"}
	
	local function AddConnection(TargetPlayer: Player, Connected: boolean?)
	    if not Connected then
	        vape:Clean(TargetPlayer:GetAttributeChangedSignal("Team"):Connect(function()
	            AddConnection(TargetPlayer, true)
	        end))
	    end
	
	    local Name: string = `{TargetPlayer.DisplayName} ({TargetPlayer.Name})`
	    if TargetPlayer:GetAttribute("Team") == LocalPlayer:GetAttribute("Team") and not table.find(Friends, Name) then
	        table.insert(Friends, Name)
	        FrostySlime:Change(Friends)
	        HealSlime:Change(Friends)
	        StickySlime:Change(Friends)
	        VoidSlime:Change(Friends)
	    end
	end
	
	Notify = AutoNoelle:CreateToggle({Name = "Notify on direct"})
	
	Limit = AutoNoelle:CreateToggle({Name = "Limit to item"})
	
	FrostySlime = AutoNoelle:CreateDropdown({
	    Name = "Frosty Slime Target",
	    List = {},
	    Tooltip = "Player to direct frost slimes to"
	})
	HealSlime = AutoNoelle:CreateDropdown({
	    Name = "Heal Slime Target",
	    List = {},
	    Tooltip = "Player to direct heal slimes to"
	})
	StickySlime = AutoNoelle:CreateDropdown({
	    Name = "Sticky Slime Target",
	    List = {},
	    Tooltip = "Player to direct sticky slimes to"
	})
	VoidSlime = AutoNoelle:CreateDropdown({
	    Name = "Void Slime Target",
	    List = {},
	    Tooltip = "Player to direct void slimes to"
	})
	for _, v: Player in Players:GetPlayers() do
	    AddConnection(v)
	end
	vape:Clean(Players.PlayerAdded:Connect(AddConnection))
end)

