Run(function()
	local AutoUma
	local Range
	local Limit
	local Animation
	local AutoSummon
	local HealSpirit
	local AttackSpirit
	local TargetItemDrops
	local Diamond
	local Emerald
	
	local function GetAttackData()
	    if Limit.Enabled then
	        local Tool: Tool? = (Store.hand.tool and Store.hand.tool.Name == "spirit_staff") and Store.hand.tool or nil
	        return Tool, Tool and GetHotbar(Tool) or nil
	    end
	    for i: number, v: any in Store.inventory.inventory.items do
	        if v.itemType == "spirit_staff" and v.tool then
	            SwitchItem(v.tool, 0)
	            return v.tool, i
	        end
	    end
	    return
	end
	
	local RayCheck: RaycastParams = RaycastParams.new()
	RayCheck.FilterType = Enum.RaycastFilterType.Include
	
	local function FireSpirit(Staff, SpiritType: string, Drop: BasePart)
	    local Meta = Bedwars.ProjectileMeta[SpiritType]
	    if not Meta then
	        return false
	    end
	
	    local LocalPosition: Vector3 = Entity.character.RootPart.Position
	    local ShootPosition: Vector3 = LocalPosition + Vector3.new(0, 2, 0)
	    RayCheck.FilterDescendantsInstances = Store.map and {Store.map} or {}
	
	    local AimPoint: Vector3? = PredictionLib.SolveTrajectory(ShootPosition, Meta.launchVelocity, Meta.gravitationalAcceleration or 196.2, Drop.Position, Vector3.zero, workspace.Gravity, 0, 0, RayCheck)
	    if not AimPoint then
	        return false
	    end
	
	    Bedwars.Handler:Get("ProjectileFire"):Fire("CallServerAsync",
	        Staff,
	        nil,
	        SpiritType,
	        ShootPosition,
	        LocalPosition,
	        CFrame.lookAt(ShootPosition, AimPoint).LookVector * Meta.launchVelocity,
	        HttpService:GenerateGUID(true),
	        {
	            drawDurationSeconds = 1,
	            shotId = HttpService:GenerateGUID(false)
	        },
	        workspace:GetServerTimeNow() - 0.045
	    )
	
	    return true
	end
	
	local function GetDrops(LocalPosition: Vector3, ItemDrops: {BasePart})
	    local Drop, LastMagnitude = nil, Range.Value + 1
	    for _, v: BasePart in ItemDrops do
	        if v.Name == "emerald" and Emerald.Enabled or v.Name == "diamond" and Diamond.Enabled then
	            local Magnitude: number = (LocalPosition - v.Position).Magnitude
	            if Magnitude <= LastMagnitude and not Entity.Wallcheck(LocalPosition, v.Position, {Camera, LocalPlayer.Character, v}) then
	                Drop, LastMagnitude = v, Magnitude
	            end
	        end
	    end
	    return Drop
	end
	
	AutoUma = vape.Categories.Kits:CreateModule({
	    Name = "AutoUma",
	    Function = function(Callback: boolean)
	        if Callback then
	            local Items: {BasePart} = Collection("ItemDrop", AutoUma)
	            repeat
	                local Staff = GetAttackData()
	                if Staff then
	                    if TargetItemDrops.Enabled then
	                        local AttackSpirits: number = (LocalPlayer:GetAttribute("ReadySummonedAttackSpirits") or 0)
	                        local HealSpirits: number = (LocalPlayer:GetAttribute("ReadySummonedHealSpirits") or 0)
	
	                        if AutoSummon.Enabled then
	                            if AttackSpirit.Enabled and AttackSpirits < 1 and GetItem("summon_stone") then
	                                Bedwars.AbilityController:useAbility("summon_attack_spirit")
	                            end
	
	                            if HealSpirit.Enabled and HealSpirits < 1 and GetItem("summon_stone") then
	                                Bedwars.AbilityController:useAbility("summon_heal_spirit")
	                            end
	                        end
	
	                        if (HealSpirits + AttackSpirits) > 0 then
	                            local LocalPosition: Vector3 = Entity.character.RootPart.Position
	                            local Drop: BasePart? = GetDrops(LocalPosition, Items)
	                            if Drop and FireSpirit(Staff, AttackSpirits > 0 and "attack_spirit" or "heal_spirit", Drop) then
	                                if Animation.Enabled then
	                                    Bedwars.GameAnimationUtil:playAnimation(LocalPlayer.Character, Bedwars.AnimationType.WIZARD_BALL_CAST)
	                                    Bedwars.AudioManager:playAudio(Bedwars.SoundList.SPIRIT_SUMMONER_CHANGE_AFFINITY, {})
	                                end
	
	                                task.wait(1.5)
	                            end
	                        end
	                    end
	                end
	                task.wait(0.1)
	            until not AutoUma.Enabled
	        end
	    end,
	    Tooltip = "Automatically throw spirits at item drops and opponents."
	})
	
	Range = AutoUma:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 80,
	    Default = 50,
	    Decimal = 5,
	    Suffix = function(Val: number)
	        return Val >= 2 and "studs" or "stud"
	    end
	})
	Animation = AutoUma:CreateToggle({
	    Name = "Animation",
	    Default = true
	})
	Limit = AutoUma:CreateToggle({
	    Name = "Limit to item",
	    Default = true
	})
	AutoSummon = AutoUma:CreateToggle({
	    Name = "Auto Summon",
	    Function = function(Callback: boolean)
	        if AttackSpirit then
	            AttackSpirit.Object.Visible = Callback
	            HealSpirit.Object.Visible = Callback
	        end
	    end,
	    Tooltip = "Automattically summons spirit for you"
	})
	HealSpirit = AutoUma:CreateToggle({
	    Name = "Use heal spirit",
	    Default = true,
	    Visible = false,
	    Darker = true
	})
	AttackSpirit = AutoUma:CreateToggle({
	    Name = "Use attack spirit",
	    Default = true,
	    Visible = false,
	    Darker = true
	})
	TargetItemDrops = AutoUma:CreateToggle({
	    Name = "Target item drops",
	    Function = function(Callback: boolean)
	        if Emerald then
	            Emerald.Object.Visible = Callback
	            Diamond.Object.Visible = Callback
	        end
	    end,
	    Default = true
	})
	Emerald = AutoUma:CreateToggle({
	    Name = "Emerald",
	    Darker = true,
	    Default = true
	})
	Diamond = AutoUma:CreateToggle({
	    Name = "Diamond",
	    Darker = true,
	    Default = true
	})
end)

