	        if Callback then
	            NextFire = 0
	
	            repeat
	                if Entity.isAlive and Store.equippedKit == "mage" and Store.hand.toolType == "sword" and (tick() - Bedwars.SwordController.lastSwing) < 0.2 and tick() >= NextFire then
	                    CastSpell()
	                end
	                task.wait(0.1)
	            until not AutoWhim.Enabled
	        end
