Run(function()
	local AutoWhisper
	local Heal
	local Threshold
	local Fly
	local Owl
	local Target
	
	local Teammates: {string} = {"None"}
	local Old
	
	local function GetOwl()
	    for _, v: Instance in CollectionService:GetTagged("Owl") do
	        if v:GetAttribute("Owner") == LocalPlayer.UserId then
	            return v
	        end
	    end
	    return nil
	end
	
	local function AddConnection(TargetPlayer: Player, Connected: boolean?)
	    if not Connected then
	        vape:Clean(TargetPlayer:GetAttributeChangedSignal("Team"):Connect(function()
	            AddConnection(TargetPlayer, true)
	        end))
	    end
	
	    if TargetPlayer ~= LocalPlayer and TargetPlayer:GetAttribute("Team") == LocalPlayer:GetAttribute("Team") and not table.find(Teammates, TargetPlayer.Name) then
	        table.insert(Teammates, TargetPlayer.Name)
	        Target:Change(Teammates)
	    end
	end
	
	AutoWhisper = vape.Categories.Kits:CreateModule({
	    Name = "AutoWhisper",
	    Function = function(Callback: boolean)
	        if Callback then
	            local LowestPoint: number = math.huge
	
	            Old = Bedwars.OwlKitController.onAbilityUsed
	            Bedwars.OwlKitController.onAbilityUsed = function(self, Character, Data, ...)
	                if Owl.Enabled and Data and Data.ability == "SUMMON_OWL" and Character == LocalPlayer.Character then
	                    local TargetPlayer: Player? = Players:FindFirstChild(Target.Value)
	                    if TargetPlayer and TargetPlayer ~= LocalPlayer then
	                        Bedwars.Handler:Get("SummonOwl"):Fire("CallServer", TargetPlayer)
	                        return
	                    end
	                end
	                return Old(self, Character, Data, ...)
	            end
	
	            repeat
	                task.wait()
	            until Store.matchState ~= 0 or not AutoWhisper.Enabled
	            if not AutoWhisper.Enabled then
	                return
	            end
	
	            for _, v: BasePart in Store.blocks do
	                local Point: number = (v.Position.Y - (v.Size.Y / 2)) - 50
	                if Point < LowestPoint then
	                    LowestPoint = Point
	                end
	            end
	
	            repeat
	                if Owl.Enabled and not GetOwl() and Players:FindFirstChild(Target.Value) and Bedwars.AbilityController:canUseAbility("SUMMON_OWL", {disableBlockedAbilityAlert = true}) then
	                    Bedwars.AbilityController:useAbility("SUMMON_OWL")
	                end
	
	                local LiftReady: boolean = Fly.Enabled and workspace:GetServerTimeNow() - (LocalPlayer:GetAttribute("OwlLiftReadyTime") or 0) > 0
	                local HealReady: boolean = Heal.Enabled and workspace:GetServerTimeNow() - (LocalPlayer:GetAttribute("OwlHealReadyTime") or 0) > 0
	                if LiftReady or HealReady then
	                    for _, v: Instance in CollectionService:GetTagged("Owl") do
	                        if v:GetAttribute("Owner") == LocalPlayer.UserId then
	                            local TargetPlayer: Player? = Players:GetPlayerByUserId(v:GetAttribute("Target"))
	                            local Character: Model? = TargetPlayer and TargetPlayer.Character
	                            local Root: BasePart? = Character and Character:FindFirstChild("HumanoidRootPart")
	                            if Root then
	                                if LiftReady and Root.AssemblyLinearVelocity.Y < -10 and Root.Position.Y < LowestPoint then
	                                    Bedwars.AbilityController:useAbility("OWL_LIFT")
	                                end
	
	                                local Health: number? = Character:GetAttribute("Health")
	                                local MaxHealth: number? = Character:GetAttribute("MaxHealth")
	                                if HealReady and (Threshold.Value >= 100 or Health and MaxHealth and MaxHealth > 0 and Health / MaxHealth <= Threshold.Value / 100) then
	                                    Bedwars.AbilityController:useAbility("OWL_HEAL")
	                                end
	                            end
	                            break
	                        end
	                    end
	                end
	                task.wait(0.1)
	            until not AutoWhisper.Enabled
	        elseif Old then
	            Bedwars.OwlKitController.onAbilityUsed = Old
	            Old = nil
	        end
	    end,
	    Tooltip = "Automatically uses whisper abilities"
	})
	
	Heal = AutoWhisper:CreateToggle({
	    Name = "Heal",
	    Function = function(Callback: boolean)
	        if Threshold then
	            Threshold.Object.Visible = Callback
	        end
	    end,
	    Default = true
	})
	Threshold = AutoWhisper:CreateSlider({
	    Name = "Health",
	    Min = 1,
	    Max = 100,
	    Default = 99,
	    Darker = true,
	    Suffix = "%"
	})
	Fly = AutoWhisper:CreateToggle({
	    Name = "Fly",
	    Default = true
	})
	Owl = AutoWhisper:CreateToggle({
	    Name = "Auto owl",
	    Function = function(Callback: boolean)
	        if Target then
	            Target.Object.Visible = Callback
	        end
	    end,
	    Tooltip = "Sends the owl to the teammate you pick as soon as the ability is up"
	})
	Target = AutoWhisper:CreateDropdown({
	    Name = "Teammate",
	    List = Teammates,
	    Darker = true,
	    Visible = false,
	    Tooltip = "Who the owl gets summoned onto"
	})
	
	for _, v: Player in Players:GetPlayers() do
	    AddConnection(v)
	end
	vape:Clean(Players.PlayerAdded:Connect(AddConnection))
end)

Run(function()
	local AutoXurot
