	                AutoXurot:Clean(Action.Remote:Connect(function(Data)
	                    if IsLocal(Data) then
	                        if Data.action == "transform" then
	                            DragonForm = true
	                        elseif Data.action == "dragon_deactive" then
	                            DragonForm = false
	                        end
	                    end
	                end))
	            end
	
	            local Deactivate = Bedwars.Handler:Get("VoidDragonDeactive")
