Run(function()
	local Interface
	local HotbarOpenInventory = require(LocalPlayer.PlayerScripts.TS.controllers.global.hotbar.ui["hotbar-open-inventory"]).HotbarOpenInventory
	local HotbarHealthbar = require(LocalPlayer.PlayerScripts.TS.controllers.global.hotbar.ui.healthbar["hotbar-healthbar"]).HotbarHealthbar
	local HotbarApp = GetRoactRender(require(LocalPlayer.PlayerScripts.TS.controllers.global.hotbar.ui["hotbar-app"]).HotbarApp.render)
	local OldConstants, NewConstants = {}, {}
	
	vape:Clean(function()
	    for _, v: {[number]: any} in NewConstants do
	        table.clear(v)
	    end
	    for _, v: {[number]: any} in OldConstants do
	        table.clear(v)
	    end
	    table.clear(NewConstants)
	    table.clear(OldConstants)
	end)
	
	local function ModifyConstant(Function, Index: number, Value)
	    if not Function then
	        return
	    end
	    if not OldConstants[Function] then
	        OldConstants[Function] = {}
	    end
	    if not NewConstants[Function] then
	        NewConstants[Function] = {}
	    end
	    if not OldConstants[Function][Index] then
	        OldConstants[Function][Index] = debug.getconstant(Function, Index)
	    end
	    if typeof(OldConstants[Function][Index]) ~= typeof(Value) then
	        return
	    end
	    NewConstants[Function][Index] = Value
	
	    if Interface.Enabled then
	        if Value then
	            debug.setconstant(Function, Index, Value)
	        else
	            debug.setconstant(Function, Index, OldConstants[Function][Index])
	            OldConstants[Function][Index] = nil
	        end
	    end
	end
	
	Interface = vape.Legit:CreateModule({
	    Name = "Interface",
	    Category = "Game",
	    Icon = GetVapeAsset("kingvape/assets/new/legit_interface.png"),
	    Function = function(Callback: boolean)
	        for Function: (...any) -> ...any, Constants: {[number]: any} in (Callback and NewConstants or OldConstants) do
	            for i: number, Value: any in Constants do
	                debug.setconstant(Function, i, Value)
	            end
	        end
	    end,
	    Tooltip = "Customize bedwars UI"
	})
	
	local FontItems: {string} = {"LuckiestGuy"}
	for _, v: EnumItem in Enum.Font:GetEnumItems() do
	    if v.Name ~= "LuckiestGuy" then
	        table.insert(FontItems, v.Name)
	    end
	end
	Interface:CreateDropdown({
	    Name = "Health Font",
	    List = FontItems,
	    Function = function(Val: string)
	        ModifyConstant(HotbarHealthbar.render, 77, Val)
	    end
	})
	Interface:CreateColorSlider({
	    Name = "Health Color",
	    Function = function(Hue: number, Sat: number, Val: number)
	        ModifyConstant(HotbarHealthbar.render, 16, tonumber(Color3.fromHSV(Hue, Sat, Val):ToHex(), 16))
	        if Interface.Enabled then
	            local Hotbar = LocalPlayer.PlayerGui:FindFirstChild("hotbar")
	            Hotbar = Hotbar and Hotbar:FindFirstChild("HealthbarProgressWrapper", true)
	            if Hotbar then
	                Hotbar["1"].BackgroundColor3 = Color3.fromHSV(Hue, Sat, Val)
	            end
	        end
	    end
	})
	Interface:CreateColorSlider({
	    Name = "Hotbar Color",
	    DefaultOpacity = 0.8,
	    Function = function(Hue: number, Sat: number, Val: number, Opacity: number)
	        local InventoryRender = OldInventoryRender or HotbarOpenInventory.render
	        local AppRender = debug.getupvalue(HotbarApp, 23).render
	        ModifyConstant(AppRender, 51, tonumber(Color3.fromHSV(Hue, Sat, Val):ToHex(), 16))
	        ModifyConstant(AppRender, 58, tonumber(Color3.fromHSV(Hue, Sat, math.clamp(Val > 0.5 and Val - 0.2 or Val + 0.2, 0, 1)):ToHex(), 16))
	        ModifyConstant(AppRender, 54, 1 - Opacity)
	        ModifyConstant(AppRender, 55, math.clamp(1.2 - Opacity, 0, 1))
	        ModifyConstant(InventoryRender, 31, tonumber(Color3.fromHSV(Hue, Sat, Val):ToHex(), 16))
	        ModifyConstant(InventoryRender, 32, math.clamp(1.2 - Opacity, 0, 1))
	        ModifyConstant(InventoryRender, 34, tonumber(Color3.fromHSV(Hue, Sat, math.clamp(Val > 0.5 and Val - 0.2 or Val + 0.2, 0, 1)):ToHex(), 16))
	    end
	})
end)

Run(function()
	local KillEffect
	local Mode
	local List
	local NameToId: {[string]: any} = {}
	local Debris: Debris = cloneref(game:GetService("Debris"))
	
	local KillEffects = {
	    Gravity = function(_, _, Character: Model, _)
	        Character:BreakJoints()
	        local Highlight: Highlight? = Character:FindFirstChildWhichIsA("Highlight")
	        local Nametag: Instance? = Character:FindFirstChild("Nametag", true)
	        if Highlight then
	            Highlight:Destroy()
	        end
	        if Nametag then
	            Nametag:Destroy()
	        end
	
	        task.spawn(function()
	            local PartVelocity: {[string]: Vector3} = {}
	            for _, v: Instance in Character:GetDescendants() do
	                if v:IsA("BasePart") then
	                    PartVelocity[v.Name] = v.AssemblyLinearVelocity
	                end
	            end
	            Character.Archivable = true
	            local Clone: Model = Character:Clone()
	            Clone.Humanoid.Health = 100
	            Clone.Parent = workspace
	            Debris:AddItem(Clone, 30)
	            Character:Destroy()
	            task.wait(0.01)
	            Clone.Humanoid:ChangeState(Enum.HumanoidStateType.Dead)
	            Clone:BreakJoints()
	            task.wait(0.01)
	            for _, v: Instance in Clone:GetDescendants() do
	                if v:IsA("BasePart") then
	                    local BodyForce: BodyForce = Instance.new("BodyForce")
	                    BodyForce.Force = Vector3.new(0, (workspace.Gravity - 10) * v:GetMass(), 0)
	                    BodyForce.Parent = v
	                    v.CanCollide = true
	                    v.AssemblyLinearVelocity = PartVelocity[v.Name] or Vector3.zero
	                end
	            end
	        end)
	    end,
	    Lightning = function(_, _, Character: Model, _)
	        Character:BreakJoints()
	        local Highlight: Highlight? = Character:FindFirstChildWhichIsA("Highlight")
	        if Highlight then
	            Highlight:Destroy()
	        end
	        local StartHeight: number = 1125
	        local StartPosition: Vector3 = Character.PrimaryPart.CFrame.p - Vector3.new(0, 8, 0)
	        local NewPosition: Vector3 = Vector3.new((math.random(1, 10) - 5) * 2, StartHeight, (math.random(1, 10) - 5) * 2)
	
	        for Height: number = StartHeight - 75, 0, -75 do
	            local NextPosition: Vector3 = Vector3.new((math.random(1, 10) - 5) * 2, Height, (math.random(1, 10) - 5) * 2)
	            if Height == 0 then
	                NextPosition = Vector3.zero
	            end
	            local Part: Part = Instance.new("Part")
	            Part.Size = Vector3.new(1.5, 1.5, 77)
	            Part.Material = Enum.Material.SmoothPlastic
	            Part.Anchored = true
	            Part.Material = Enum.Material.Neon
	            Part.CanCollide = false
	            Part.CFrame = CFrame.new(StartPosition + NewPosition + ((NextPosition - NewPosition) * 0.5), StartPosition + NextPosition)
	            Part.Parent = workspace
	            local OuterPart: Part = Part:Clone()
	            OuterPart.Size = Vector3.new(3, 3, 78)
	            OuterPart.Color = Color3.new(0.7, 0.7, 0.7)
	            OuterPart.Transparency = 0.7
	            OuterPart.Material = Enum.Material.SmoothPlastic
	            OuterPart.Parent = workspace
	            Debris:AddItem(Part, 0.5)
	            Debris:AddItem(OuterPart, 0.5)
	            Bedwars.QueryUtil:setQueryIgnored(Part, true)
	            Bedwars.QueryUtil:setQueryIgnored(OuterPart, true)
	            if Height == 0 then
	                local SoundPart: Part = Instance.new("Part")
	                SoundPart.Transparency = 1
	                SoundPart.Anchored = true
	                SoundPart.Size = Vector3.zero
	                SoundPart.Position = StartPosition
	                SoundPart.Parent = workspace
	                Bedwars.QueryUtil:setQueryIgnored(SoundPart, true)
	                local Sound: Sound = Instance.new("Sound")
	                Sound.SoundId = "rbxassetid://6993372814"
	                Sound.Volume = 2
	                Sound.Pitch = 0.5 + (math.random(1, 3) / 10)
	                Sound.Parent = SoundPart
	                Sound:Play()
	                Sound.Ended:Connect(function()
	                    SoundPart:Destroy()
	                end)
	            end
	            NewPosition = NextPosition
	        end
	    end,
	    Delete = function(_, _, Character: Model, _)
	        Character:Destroy()
	    end
	}
	
	KillEffect = vape.Legit:CreateModule({
	    Name = "Kill Effect",
	    Category = "Game",
	    Icon = GetVapeAsset("kingvape/assets/new/legit_killeffect.png"),
	    Function = function(Callback: boolean)
	        if Callback then
	            for Name: string, Effect: (...any) -> ...any in KillEffects do
	                Bedwars.KillEffectController.killEffects[`Custom{Name}`] = {
	                    new = function()
	                        return {
	                            onKill = Effect,
	                            isPlayDefaultKillEffect = function()
	                                return false
	                            end
	                        }
	                    end
	                }
	            end
	            KillEffect:Clean(LocalPlayer:GetAttributeChangedSignal("KillEffectType"):Connect(function()
	                LocalPlayer:SetAttribute("KillEffectType", Mode.Value == "Bedwars" and NameToId[List.Value] or `Custom{Mode.Value}`)
	            end))
	            LocalPlayer:SetAttribute("KillEffectType", Mode.Value == "Bedwars" and NameToId[List.Value] or `Custom{Mode.Value}`)
	        else
	            for Name: string in KillEffects do
	                Bedwars.KillEffectController.killEffects[`Custom{Name}`] = nil
	            end
	            LocalPlayer:SetAttribute("KillEffectType", "default")
	        end
	    end,
	    Tooltip = "Custom final kill effects"
	})
	
	local Modes: {string} = {"Bedwars"}
	for Name: string in KillEffects do
	    table.insert(Modes, Name)
	end
	Mode = KillEffect:CreateDropdown({
	    Name = "Mode",
	    List = Modes,
	    Function = function(Val: string)
	        if List then
	            List.Object.Visible = Val == "Bedwars"
	        end
	        if KillEffect.Enabled then
	            LocalPlayer:SetAttribute("KillEffectType", Val == "Bedwars" and NameToId[List.Value] or `Custom{Val}`)
	        end
	    end
	})
	local KillEffectName: {string} = {}
	for EffectId: string, v: any in Bedwars.KillEffectMeta do
	    table.insert(KillEffectName, v.name)
	    NameToId[v.name] = EffectId
	end
	table.sort(KillEffectName)
	List = KillEffect:CreateDropdown({
	    Name = "Bedwars",
	    List = KillEffectName,
	    Function = function(Val: string)
	        if KillEffect.Enabled then
	            LocalPlayer:SetAttribute("KillEffectType", NameToId[Val])
	        end
	    end,
	    Darker = true
	})
end)

Run(function()
    local Ping
    local Label: TextLabel

    Ping = vape.Legit:CreateModule({
        Name = "Ping",
        Category = "HUD",
        Icon = GetVapeAsset("kingvape/assets/new/legit_ping.png"),
        Function = function(Callback: boolean)
            if Callback then
                repeat
                    Label.Text = `{math.floor(math.max(Store.ping.incoming or 0, Store.ping.total or 0) * 1000)} ms`
                    task.wait(0.1)
                until not Ping.Enabled
            end
        end,
        Size = UDim2.fromOffset(100, 41),
        Tooltip = "Shows the current connection speed to the game server"
    })

    Ping:CreateFont({
        Name = "Font",
        Blacklist = "Gotham",
        Function = function(FontFace: Font)
            Label.FontFace = FontFace
        end
    })
    Ping:CreateColorSlider({
        Name = "Color",
        DefaultValue = 0,
        DefaultOpacity = 0.5,
        Function = function(Hue: number, Sat: number, Val: number, Opacity: number)
            Label.BackgroundColor3 = Color3.fromHSV(Hue, Sat, Val)
            Label.BackgroundTransparency = 1 - Opacity
        end
    })
    Label = Instance.new("TextLabel")
    Label.Size = UDim2.new(0, 100, 0, 41)
    Label.BackgroundTransparency = 0.5
    Label.TextSize = 15
    Label.FontFace = UIPallet.Font
    Label.Text = "0 ms"
    Label.TextColor3 = Color3.new(1, 1, 1)
    Label.BackgroundColor3 = Color3.new()
    Label.Parent = Ping.Children
    local Corner: UICorner = Instance.new("UICorner")
    Corner.CornerRadius = UDim.new(0, 4)
    Corner.Parent = Label
end)
task.spawn(function()
    local Incoming: number?
    repeat
        if not Incoming then
            Incoming = os.clock()
            task.spawn(function()
                Bedwars.Handler:Get("FetchServerRegion"):Fire("CallServer")
                Store.ping.total = os.clock() - Incoming
                Incoming = nil
            end)
        end
        Store.ping.incoming = os.clock() - Incoming
        task.wait(1)
    until vape.Loaded == nil
end)

Run(function()
	local PotionStatus
	local ShowPositive
	local ShowNegative
	local Background
	local BackgroundColor
	local Effects: {[string]: number} = {}
	local Seen: {[string]: boolean} = {}
	local Replacements: {[string]: string} = {
	    speed = "rbxassetid://71873445837330"
	}
	local Negative: {[string]: boolean} = {
	    bleed = true,
	    burn = true,
	    cold = true,
	    curse_of_the_altar = true,
	    decay = true,
	    dizzy = true,
	    feeble = true,
	    frost_bite = true,
	    frosted = true,
	    frozen = true,
	    grave_trap = true,
	    greased = true,
	    grounded = true,
	    grounded_enchant = true,
	    hungry = true,
	    infected_poison = true,
	    isabel_shield_broken = true,
	    lunar_venom = true,
	    mage_burn = true,
	    oil_spilled = true,
	    oiled = true,
	    on_ice = true,
	    owl_target = true,
	    poison = true,
	    powdered = true,
	    shield_down = true,
	    shrink = true,
	    silas_halloween_hex = true,
	    silence = true,
	    skeleton_poison = true,
	    snae_poison_arrow = true,
	    snake_poison_sword = true,
	    soaked = true,
	    SPIDER_WEB_SLOW = true,
	    stacking_decay = true,
	    Vengeful_venom = true,
	    void_hunter_marked = true,
	    weak_armor = true,
	    werewolf_fear = true,
	    zapped_1 = true,
	    zapped_2 = true,
	    zapped_3 = true
	}
	local AccentColor: Color3 = Color3.fromRGB(5, 134, 105)
	local WarnColor: Color3 = Color3.fromRGB(236, 129, 44)
	local DangerColor: Color3 = Color3.fromRGB(250, 50, 56)
	local HalfCut: NumberSequence = NumberSequence.new({
	    NumberSequenceKeypoint.new(0, 0),
	    NumberSequenceKeypoint.new(0.5, 0),
	    NumberSequenceKeypoint.new(0.501, 1),
	    NumberSequenceKeypoint.new(1, 1)
	})
	local Holder: Frame
	
	local function Added(Active)
	    if vape.ThreadFix then
	        setthreadidentity(8)
	    end
	
	    Effects[Active.statusEffect] = Active.expireTime
	    local Duration: number = Active.expireTime - workspace:GetServerTimeNow()
	    if Duration <= 0 then
	        Effects[Active.statusEffect] = nil
	        return
	    end
	
	    local ItemMeta = Bedwars.ItemMeta[Active.statusEffect] or Bedwars.ItemMeta[`{Active.statusEffect}_potion`]
	    local Effect: Frame = Instance.new("Frame")
	    Effect.BackgroundTransparency = 1
	    Effect.Parent = Holder
	    local Ring: Frame = Instance.new("Frame")
	    Ring.BackgroundTransparency = 1
	    Ring.Position = UDim2.fromOffset(0, 4)
	    Ring.Size = UDim2.fromOffset(50, 50)
	    Ring.Parent = Effect
	    local Backing: Frame = Instance.new("Frame")
	    Backing.BackgroundTransparency = 1
	    Backing.Position = UDim2.fromOffset(4.5, 4.5)
	    Backing.Size = UDim2.fromOffset(41, 41)
	    Backing.Parent = Ring
	    local BackingCorner: UICorner = Instance.new("UICorner")
	    BackingCorner.CornerRadius = UDim.new(1, 0)
	    BackingCorner.Parent = Backing
	    local BackingStroke: UIStroke = Instance.new("UIStroke")
	    BackingStroke.Color = Color3.new()
	    BackingStroke.Thickness = 3.6
	    BackingStroke.Transparency = 0.216
	    BackingStroke.Parent = Backing
	    local Gradients, Strokes = {}, {}
	
	    for _, Side: string in {"Left", "Right"} do
	        local Clip: Frame = Instance.new("Frame")
	        Clip.BackgroundTransparency = 1
	        Clip.ClipsDescendants = true
	        Clip.Position = UDim2.fromOffset(Side == "Right" and 25 or 0, 0)
	        Clip.Size = UDim2.fromOffset(25, 50)
	        Clip.Parent = Ring
	        local Arc: Frame = Instance.new("Frame")
	        Arc.BackgroundTransparency = 1
	        Arc.Position = UDim2.fromOffset(Side == "Right" and -21 or 4, 4)
	        Arc.Size = UDim2.fromOffset(42, 42)
	        Arc.Parent = Clip
	        local ArcCorner: UICorner = Instance.new("UICorner")
	        ArcCorner.CornerRadius = UDim.new(1, 0)
	        ArcCorner.Parent = Arc
	        local ArcStroke: UIStroke = Instance.new("UIStroke")
	        ArcStroke.Color = AccentColor
	        ArcStroke.Thickness = 4
	        ArcStroke.Parent = Arc
	        local ArcGradient: UIGradient = Instance.new("UIGradient")
	        ArcGradient.Transparency = HalfCut
	        ArcGradient.Parent = ArcStroke
	        Gradients[Side] = ArcGradient
	        Strokes[Side] = ArcStroke
	    end
	
	    local Sidebar: Frame = Instance.new("Frame")
	    Sidebar.AnchorPoint = Vector2.new(0, 0.5)
	    Sidebar.BackgroundColor3 = Color3.fromRGB(170, 170, 170)
	    Sidebar.BackgroundTransparency = 0.5
	    Sidebar.BorderSizePixel = 0
	    Sidebar.Position = UDim2.new(0, 53, 0.5, 1)
	    Sidebar.Size = UDim2.fromOffset(2, 27)
	    Sidebar.Parent = Effect
	    local EffectImage: ImageLabel = Instance.new("ImageLabel")
	    EffectImage.AnchorPoint = Vector2.new(0, 0.5)
	    EffectImage.BackgroundTransparency = 1
	    EffectImage.Image = Replacements[Active.statusEffect] or (ItemMeta and ItemMeta.image) or Bedwars.ImageList.POTION_ART
	    EffectImage.Position = UDim2.new(0, 10, 0.5, 0)
	    EffectImage.Size = UDim2.fromOffset(30, 30)
	    EffectImage.Parent = Effect
	    local EffectName: TextLabel = Instance.new("TextLabel")
	    EffectName.BackgroundTransparency = 1
	    EffectName.FontFace = UIPallet.FontBold
	    EffectName.Position = UDim2.fromOffset(67, 10)
	    EffectName.Size = UDim2.fromOffset(108, 20)
	    EffectName.Text = (`{Active.statusEffect:sub(0, 1):upper()}{Active.statusEffect:sub(2, #Active.statusEffect)}`):gsub("_", " ")
	    EffectName.TextColor3 = Color3.new(1, 1, 1)
	    EffectName.TextSize = 15
	    EffectName.TextXAlignment = Enum.TextXAlignment.Left
	    EffectName.Parent = Effect
	    local NameShadow: TextLabel = EffectName:Clone()
	    NameShadow.Position += UDim2.fromOffset(1, 1)
	    NameShadow.TextColor3 = Color3.new()
	    NameShadow.TextTransparency = 0.5
	    NameShadow.ZIndex = 0
	    NameShadow.Parent = Effect
	    Effect.Size = UDim2.fromOffset(GetFontBounds(EffectName.Text, 15, UIPallet.FontBold).X + 80, 57)
	    local EffectDuration: TextLabel = EffectName:Clone()
	    EffectDuration.Position = UDim2.fromOffset(67, 29)
	    EffectDuration.Text = "00:00"
	    EffectDuration.TextSize = 14
	    EffectDuration.Parent = Effect
	    local DurationShadow: TextLabel = EffectDuration:Clone()
	    DurationShadow.Position += UDim2.fromOffset(1, 1)
	    DurationShadow.TextColor3 = Color3.new()
	    DurationShadow.TextTransparency = 0.5
	    DurationShadow.ZIndex = 0
	    DurationShadow.Parent = Effect
	    local Seconds: number = 0
	
	    repeat
	        local Remaining: number = math.max(Active.expireTime - workspace:GetServerTimeNow(), 0)
	        local Percent: number = Remaining / Duration
	        local RingColor: Color3 = Percent > 0.5 and AccentColor or (Percent > 0.25 and WarnColor or DangerColor)
	        local Theta: number = math.min(Percent, 1) * 360
	        Seconds = math.floor(Remaining)
	        Gradients.Left.Rotation = math.clamp(Theta, 180, 360)
	        Gradients.Right.Rotation = math.clamp(Theta, 0, 180)
	        Strokes.Left.Color = RingColor
	        Strokes.Right.Color = RingColor
	        EffectDuration.Text = ("%02d:%02d"):format(Seconds // 60, Seconds % 60)
	        EffectDuration.TextColor3 = RingColor
	        DurationShadow.Text = EffectDuration.Text
	        task.wait()
	    until Seconds <= 0 or Effects[Active.statusEffect] ~= Active.expireTime
	
	    Effect:Destroy()
	
	    if Effects[Active.statusEffect] == Active.expireTime then
	        Effects[Active.statusEffect] = nil
	    end
	end
	
	PotionStatus = vape.Legit:CreateModule({
	    Name = "Potion Status",
	    Category = "HUD",
	    Icon = GetVapeAsset("kingvape/assets/new/legit_potionstatus.png"),
	    Function = function(Callback: boolean)
	        if Callback then
	            repeat
	                table.clear(Seen)
	
	                if Entity.isAlive then
	                    for _, v: any in Bedwars.StatusEffectUtil:getAllActive(LocalPlayer.Character) do
	                        if (v.expireTime or 0) - workspace:GetServerTimeNow() > 0 and (Negative[v.statusEffect] and ShowNegative.Enabled or not Negative[v.statusEffect] and ShowPositive.Enabled) then
	                            Seen[v.statusEffect] = true
	
	                            if Effects[v.statusEffect] ~= v.expireTime then
	                                task.spawn(Added, v)
	                            end
	                        end
	                    end
	                end
	
	                for StatusEffect: string in Effects do
	                    if not Seen[StatusEffect] then
	                        Effects[StatusEffect] = nil
	                    end
	                end
	
	                task.wait(0.1)
	            until not PotionStatus.Enabled
	
	            table.clear(Effects)
	        end
	    end,
	    Size = UDim2.fromOffset(240, 64),
	    Tooltip = "Shows your currently active effects"
	})
	
	Holder = PotionStatus.Children
	Holder.BackgroundColor3 = Color3.new()
	Holder.BackgroundTransparency = 0.5
	local HolderCorner: UICorner = Instance.new("UICorner")
	HolderCorner.CornerRadius = UDim.new(0, 4)
	HolderCorner.Parent = Holder
	local Layout: UIListLayout = Instance.new("UIListLayout")
	Layout.HorizontalAlignment = Enum.HorizontalAlignment.Left
	Layout.SortOrder = Enum.SortOrder.LayoutOrder
	Layout.Parent = Holder
	vape:Clean(Layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
	    if vape.ThreadFix then
	        setthreadidentity(8)
	    end
	
	    Holder.Size = UDim2.fromOffset(Layout.AbsoluteContentSize.X, Layout.AbsoluteContentSize.Y)
	end))
	ShowPositive = PotionStatus:CreateToggle({
	    Name = "Show Positive Effects",
